-- Name: activate_key_as_service(uuid, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.activate_key_as_service(p_user_id uuid, p_key_code text) RETURNS TABLE(success boolean, error text, key_type text, membership_type text, credits_amount integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_key activation_keys%ROWTYPE;
    v_current_credits INT;
    v_new_credits INT;
    v_current_membership text;
    v_current_membership_expires_at timestamptz;
    v_effective_membership text;
    v_next_expires_at timestamptz;
    v_now timestamptz := now();
BEGIN
IF auth.role() <> 'service_role' THEN
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
END IF;
    IF p_key_code IS NULL OR length(trim(p_key_code)) = 0 THEN
        RETURN QUERY SELECT false, '激活码不能为空', NULL, NULL, NULL;
        RETURN;
    END IF;
    SELECT * INTO v_key
    FROM public.activation_keys
    WHERE key_code = p_key_code
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false, '激活码不存在', NULL, NULL, NULL;
        RETURN;
    END IF;
    IF v_key.is_used THEN
        RETURN QUERY SELECT false, '该激活码已被使用', v_key.key_type, v_key.membership_type, v_key.credits_amount;
        RETURN;
    END IF;
    IF v_key.key_type = 'membership' THEN
        IF v_key.membership_type NOT IN ('plus', 'pro') THEN
            RETURN QUERY SELECT false, '无效的会员类型', v_key.key_type, v_key.membership_type, NULL;
            RETURN;
        END IF;
        SELECT membership, membership_expires_at
        INTO v_current_membership, v_current_membership_expires_at
        FROM public.users
        WHERE id = p_user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RETURN QUERY SELECT false, '获取用户信息失败', v_key.key_type, v_key.membership_type, NULL;
            RETURN;
        END IF;
        v_effective_membership := CASE
            WHEN v_current_membership IN ('plus', 'pro')
                AND v_current_membership_expires_at IS NOT NULL
                AND v_current_membership_expires_at > v_now
              THEN v_current_membership
            ELSE 'free'
        END;
        IF public.membership_rank(v_effective_membership) > public.membership_rank(v_key.membership_type) THEN
            RETURN QUERY SELECT false, '当前已有更高等级会员', v_key.key_type, v_key.membership_type, NULL;
            RETURN;
        END IF;
        IF public.membership_rank(v_effective_membership) = public.membership_rank(v_key.membership_type)
            AND v_effective_membership <> 'free'
            AND v_current_membership_expires_at IS NOT NULL
            AND v_current_membership_expires_at > v_now THEN
            v_next_expires_at := v_current_membership_expires_at + INTERVAL '30 days';
        ELSE
            v_next_expires_at := v_now + INTERVAL '30 days';
        END IF;
        UPDATE public.users
        SET
            membership = v_key.membership_type,
            membership_expires_at = v_next_expires_at,
            updated_at = now()
        WHERE id = p_user_id;
    ELSE
        IF COALESCE(v_key.credits_amount, 0) <= 0 THEN
            RETURN QUERY SELECT false, '无效的积分数量', v_key.key_type, NULL, NULL;
            RETURN;
        END IF;
        SELECT COALESCE(ai_chat_count, 0)
        INTO v_current_credits
        FROM public.users
        WHERE id = p_user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RETURN QUERY SELECT false, '获取用户信息失败', v_key.key_type, NULL, NULL;
            RETURN;
        END IF;
        v_new_credits := v_current_credits + COALESCE(v_key.credits_amount, 0);
        UPDATE public.users
        SET
            ai_chat_count = v_new_credits,
            updated_at = now()
        WHERE id = p_user_id;
        PERFORM public.record_credit_transaction(
            p_user_id,
            COALESCE(v_key.credits_amount, 0),
            'earn',
            'activation_key',
            v_new_credits,
            'activation_key',
            v_key.id::text,
            format('激活码充值 +%s 积分', COALESCE(v_key.credits_amount, 0)),
            jsonb_build_object('key_source', COALESCE(v_key.source, 'admin'))
        );
    END IF;
    UPDATE public.activation_keys
    SET
        is_used = true,
        used_by = p_user_id,
        used_at = now()
    WHERE id = v_key.id AND is_used = false;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false, '激活失败，请重试', v_key.key_type, v_key.membership_type, v_key.credits_amount;
        RETURN;
    END IF;
    RETURN QUERY SELECT true, NULL, v_key.key_type, v_key.membership_type, v_key.credits_amount;
END;
$$;

-- Name: admin_create_ai_model_binding(text, text, text, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.admin_create_ai_model_binding(p_model_id text, p_source_key text, p_model_id_override text DEFAULT NULL::text, p_reasoning_model_id text DEFAULT NULL::text, p_is_enabled boolean DEFAULT true, p_priority integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_model_id text;
  v_model_key text;
  v_gateway_id text;
  v_priority integer;
  v_normalized_model_id_override text;
  v_binding public.ai_model_gateway_bindings;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT
    id::text,
    model_key
  INTO
    v_model_id,
    v_model_key
  FROM public.ai_models
  WHERE id::text = p_model_id
  FOR UPDATE;
  IF v_model_id IS NULL THEN
    RETURN jsonb_build_object('status', 'model_not_found');
  END IF;
  SELECT id::text
  INTO v_gateway_id
  FROM public.ai_gateways
  WHERE gateway_key = p_source_key
  FOR UPDATE;
  IF v_gateway_id IS NULL THEN
    RETURN jsonb_build_object('status', 'gateway_not_found');
  END IF;
  SELECT COALESCE(MAX(priority), -1) + 1
  INTO v_priority
  FROM public.ai_model_gateway_bindings
  WHERE model_id::text = v_model_id;
  v_normalized_model_id_override := NULLIF(BTRIM(COALESCE(p_model_id_override, '')), '');
  IF v_normalized_model_id_override = v_model_key THEN
    v_normalized_model_id_override := NULL;
  END IF;
  INSERT INTO public.ai_model_gateway_bindings (
    model_id,
    gateway_id,
    model_id_override,
    reasoning_model_id,
    is_enabled,
    priority,
    notes
  )
  VALUES (
    v_model_id::uuid,
    v_gateway_id::uuid,
    v_normalized_model_id_override,
    NULLIF(BTRIM(COALESCE(p_reasoning_model_id, '')), ''),
    COALESCE(p_is_enabled, true),
    COALESCE(p_priority, v_priority),
    p_notes
  )
  RETURNING *
  INTO v_binding;
  RETURN jsonb_build_object(
    'status', 'ok',
    'binding', to_jsonb(v_binding)
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('status', 'conflict');
END;
$$;

-- Name: admin_create_ai_model_with_binding(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.admin_create_ai_model_with_binding(p_model jsonb, p_primary_gateway_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gateway_id uuid;
  v_model public.ai_models;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT id
  INTO v_gateway_id
  FROM public.ai_gateways
  WHERE gateway_key = p_primary_gateway_key;
  IF v_gateway_id IS NULL THEN
    RETURN jsonb_build_object('status', 'gateway_not_found');
  END IF;
  INSERT INTO public.ai_models (
    model_key,
    display_name,
    vendor,
    usage_type,
    routing_mode,
    is_enabled,
    sort_order,
    required_tier,
    supports_reasoning,
    reasoning_required_tier,
    is_reasoning_default,
    supports_vision,
    default_temperature,
    default_top_p,
    default_presence_penalty,
    default_frequency_penalty,
    default_max_tokens,
    default_reasoning_effort,
    reasoning_effort_format,
    custom_parameters,
    description
  )
  VALUES (
    NULLIF(p_model->>'model_key', ''),
    NULLIF(p_model->>'display_name', ''),
    NULLIF(p_model->>'vendor', ''),
    COALESCE(NULLIF(p_model->>'usage_type', ''), 'chat'),
    COALESCE(NULLIF(p_model->>'routing_mode', ''), 'auto'),
    COALESCE((p_model->>'is_enabled')::boolean, true),
    COALESCE((p_model->>'sort_order')::integer, 0),
    COALESCE(NULLIF(p_model->>'required_tier', ''), 'free'),
    COALESCE((p_model->>'supports_reasoning')::boolean, false),
    COALESCE(NULLIF(p_model->>'reasoning_required_tier', ''), 'plus'),
    COALESCE((p_model->>'is_reasoning_default')::boolean, false),
    COALESCE((p_model->>'supports_vision')::boolean, false),
    CASE WHEN p_model ? 'default_temperature' THEN (p_model->>'default_temperature')::numeric ELSE NULL END,
    CASE WHEN p_model ? 'default_top_p' THEN (p_model->>'default_top_p')::numeric ELSE NULL END,
    CASE WHEN p_model ? 'default_presence_penalty' THEN (p_model->>'default_presence_penalty')::numeric ELSE NULL END,
    CASE WHEN p_model ? 'default_frequency_penalty' THEN (p_model->>'default_frequency_penalty')::numeric ELSE NULL END,
    CASE WHEN p_model ? 'default_max_tokens' THEN (p_model->>'default_max_tokens')::integer ELSE NULL END,
    CASE WHEN p_model ? 'default_reasoning_effort' THEN NULLIF(p_model->>'default_reasoning_effort', '') ELSE NULL END,
    CASE WHEN p_model ? 'reasoning_effort_format' THEN NULLIF(p_model->>'reasoning_effort_format', '') ELSE NULL END,
    CASE
      WHEN p_model ? 'custom_parameters' THEN
        CASE
          WHEN jsonb_typeof(p_model->'custom_parameters') = 'null' THEN NULL
          ELSE p_model->'custom_parameters'
        END
      ELSE NULL
    END,
    CASE WHEN p_model ? 'description' THEN p_model->>'description' ELSE NULL END
  )
  RETURNING *
  INTO v_model;
  INSERT INTO public.ai_model_gateway_bindings (
    model_id,
    gateway_id,
    model_id_override,
    reasoning_model_id,
    is_enabled,
    priority,
    notes
  )
  VALUES (
    v_model.id,
    v_gateway_id,
    NULL,
    NULL,
    true,
    0,
    'Auto-created primary binding'
  );
  RETURN jsonb_build_object(
    'status', 'ok',
    'model', to_jsonb(v_model)
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('status', 'conflict');
END;
$$;

-- Name: admin_get_auth_user_emails(uuid[]); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.admin_get_auth_user_emails(p_user_ids uuid[]) RETURNS TABLE(user_id uuid, email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'identity'
    AS $$
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'Only admin can read auth user emails' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT au.id, au.email::text
  FROM identity.users au
  WHERE au.id = ANY (p_user_ids);
END;
$$;

-- Name: admin_update_ai_model_and_cleanup_bindings(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.admin_update_ai_model_and_cleanup_bindings(p_model_id text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_previous_model_key text;
  v_model public.ai_models;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT model_key
  INTO v_previous_model_key
  FROM public.ai_models
  WHERE id::text = p_model_id;
  IF v_previous_model_key IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  UPDATE public.ai_models
  SET
    model_key = CASE WHEN p_patch ? 'model_key' THEN p_patch->>'model_key' ELSE model_key END,
    display_name = CASE WHEN p_patch ? 'display_name' THEN p_patch->>'display_name' ELSE display_name END,
    vendor = CASE WHEN p_patch ? 'vendor' THEN p_patch->>'vendor' ELSE vendor END,
    usage_type = CASE WHEN p_patch ? 'usage_type' THEN p_patch->>'usage_type' ELSE usage_type END,
    routing_mode = CASE WHEN p_patch ? 'routing_mode' THEN p_patch->>'routing_mode' ELSE routing_mode END,
    is_enabled = CASE WHEN p_patch ? 'is_enabled' THEN (p_patch->>'is_enabled')::boolean ELSE is_enabled END,
    sort_order = CASE WHEN p_patch ? 'sort_order' THEN (p_patch->>'sort_order')::integer ELSE sort_order END,
    required_tier = CASE WHEN p_patch ? 'required_tier' THEN p_patch->>'required_tier' ELSE required_tier END,
    supports_reasoning = CASE WHEN p_patch ? 'supports_reasoning' THEN (p_patch->>'supports_reasoning')::boolean ELSE supports_reasoning END,
    reasoning_required_tier = CASE WHEN p_patch ? 'reasoning_required_tier' THEN p_patch->>'reasoning_required_tier' ELSE reasoning_required_tier END,
    is_reasoning_default = CASE WHEN p_patch ? 'is_reasoning_default' THEN (p_patch->>'is_reasoning_default')::boolean ELSE is_reasoning_default END,
    supports_vision = CASE WHEN p_patch ? 'supports_vision' THEN (p_patch->>'supports_vision')::boolean ELSE supports_vision END,
    default_temperature = CASE WHEN p_patch ? 'default_temperature' THEN (p_patch->>'default_temperature')::numeric ELSE default_temperature END,
    default_top_p = CASE WHEN p_patch ? 'default_top_p' THEN (p_patch->>'default_top_p')::numeric ELSE default_top_p END,
    default_presence_penalty = CASE WHEN p_patch ? 'default_presence_penalty' THEN (p_patch->>'default_presence_penalty')::numeric ELSE default_presence_penalty END,
    default_frequency_penalty = CASE WHEN p_patch ? 'default_frequency_penalty' THEN (p_patch->>'default_frequency_penalty')::numeric ELSE default_frequency_penalty END,
    default_max_tokens = CASE WHEN p_patch ? 'default_max_tokens' THEN (p_patch->>'default_max_tokens')::integer ELSE default_max_tokens END,
    default_reasoning_effort = CASE WHEN p_patch ? 'default_reasoning_effort' THEN NULLIF(p_patch->>'default_reasoning_effort', '') ELSE default_reasoning_effort END,
    reasoning_effort_format = CASE WHEN p_patch ? 'reasoning_effort_format' THEN NULLIF(p_patch->>'reasoning_effort_format', '') ELSE reasoning_effort_format END,
    custom_parameters = CASE
      WHEN p_patch ? 'custom_parameters' THEN
        CASE
          WHEN jsonb_typeof(p_patch->'custom_parameters') = 'null' THEN NULL
          ELSE p_patch->'custom_parameters'
        END
      ELSE custom_parameters
    END,
    description = CASE WHEN p_patch ? 'description' THEN p_patch->>'description' ELSE description END
  WHERE id::text = p_model_id
  RETURNING *
  INTO v_model;
  IF v_previous_model_key IS DISTINCT FROM v_model.model_key THEN
    UPDATE public.ai_model_gateway_bindings
    SET model_id_override = NULL
    WHERE model_id = v_model.id
      AND model_id_override = v_previous_model_key;
  END IF;
  RETURN jsonb_build_object(
    'status', 'ok',
    'model', to_jsonb(v_model)
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('status', 'conflict');
END;
$$;

-- Name: admin_update_ai_model_binding(text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.admin_update_ai_model_binding(p_model_id text, p_source_id text, p_patch jsonb DEFAULT '{}'::jsonb, p_activate boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_binding public.ai_model_gateway_bindings;
  v_binding_id uuid;
  v_gateway_key text;
  v_gateway_enabled boolean;
  v_model_key text;
  v_normalized_model_id_override text;
  v_next_enabled boolean;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT model_key
  INTO v_model_key
  FROM public.ai_models
  WHERE id::text = p_model_id
  FOR UPDATE;
  IF v_model_key IS NULL THEN
    RETURN jsonb_build_object('status', 'model_not_found');
  END IF;
  SELECT
    binding.id,
    gateway.gateway_key,
    gateway.is_enabled
  INTO
    v_binding_id,
    v_gateway_key,
    v_gateway_enabled
  FROM public.ai_model_gateway_bindings AS binding
  LEFT JOIN public.ai_gateways AS gateway
    ON gateway.id = binding.gateway_id
  WHERE binding.id::text = p_source_id
    AND binding.model_id::text = p_model_id
  FOR UPDATE OF binding;
  IF v_binding_id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  SELECT *
  INTO v_binding
  FROM public.ai_model_gateway_bindings
  WHERE id = v_binding_id;
  IF v_gateway_key IS NULL OR v_gateway_key NOT IN ('newapi', 'octopus') THEN
    RETURN jsonb_build_object('status', 'unsupported_source');
  END IF;
  IF p_patch ? 'model_id_override' THEN
    IF jsonb_typeof(p_patch->'model_id_override') = 'null' THEN
      v_normalized_model_id_override := NULL;
    ELSE
      v_normalized_model_id_override := NULLIF(BTRIM(p_patch->>'model_id_override'), '');
      IF v_normalized_model_id_override = v_model_key THEN
        v_normalized_model_id_override := NULL;
      END IF;
    END IF;
  END IF;
  v_next_enabled := CASE
    WHEN p_patch ? 'is_enabled' THEN COALESCE((p_patch->>'is_enabled')::boolean, false)
    ELSE COALESCE(v_binding.is_enabled, true)
  END;
  IF p_activate AND (NOT v_next_enabled OR COALESCE(v_gateway_enabled, true) = false) THEN
    RETURN jsonb_build_object('status', 'disabled_cannot_activate');
  END IF;
  UPDATE public.ai_model_gateway_bindings
  SET
    model_id_override = CASE
      WHEN p_patch ? 'model_id_override' THEN v_normalized_model_id_override
      ELSE model_id_override
    END,
    reasoning_model_id = CASE
      WHEN p_patch ? 'reasoning_model_id' THEN
        CASE
          WHEN jsonb_typeof(p_patch->'reasoning_model_id') = 'null' THEN NULL
          ELSE NULLIF(BTRIM(p_patch->>'reasoning_model_id'), '')
        END
      ELSE reasoning_model_id
    END,
    is_enabled = CASE
      WHEN p_patch ? 'is_enabled' THEN COALESCE((p_patch->>'is_enabled')::boolean, false)
      ELSE is_enabled
    END,
    priority = CASE
      WHEN p_patch ? 'priority' THEN (p_patch->>'priority')::integer
      ELSE priority
    END,
    notes = CASE
      WHEN p_patch ? 'notes' THEN
        CASE
          WHEN jsonb_typeof(p_patch->'notes') = 'null' THEN NULL
          ELSE p_patch->>'notes'
        END
      ELSE notes
    END,
    updated_at = now()
  WHERE id = v_binding.id
  RETURNING *
  INTO v_binding;
  IF p_activate THEN
    WITH ordered AS (
      SELECT
        id,
        row_number() OVER (
          ORDER BY
            CASE WHEN id = v_binding.id THEN 0 ELSE 1 END,
            priority ASC,
            id ASC
        ) - 1 AS new_priority
      FROM public.ai_model_gateway_bindings
      WHERE model_id::text = p_model_id
    )
    UPDATE public.ai_model_gateway_bindings AS binding
    SET priority = ordered.new_priority
    FROM ordered
    WHERE binding.id = ordered.id;
    SELECT *
    INTO v_binding
    FROM public.ai_model_gateway_bindings
    WHERE id = v_binding.id;
  END IF;
  RETURN jsonb_build_object(
    'status', 'ok',
    'binding', to_jsonb(v_binding)
  );
END;
$$;

-- Name: agent_admin_task_log(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_admin_task_log(p_run_id uuid, p_after bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM public.agent_require_admin();
  IF p_after<0 THEN RAISE EXCEPTION 'AGENT_DURABLE_CURSOR_INVALID' USING ERRCODE='22023'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sequence',c.sequence,'at',c.created_at,'writes',c.writes) ORDER BY c.sequence),'[]')
    INTO result
    FROM (
      SELECT d.sequence,d.created_at,coalesce((
          SELECT jsonb_agg(kept.write ORDER BY kept.n)
          FROM (
            SELECT items.n,CASE items.w->>'type'
              WHEN 'task' THEN items.w #- '{value,memos}'
              WHEN 'entry' THEN (
                SELECT jsonb_build_object('type','entry','value',jsonb_build_object(
                    'id',items.w#>'{value,id}','conversationId',items.w#>'{value,conversationId}','kind',items.w#>'{value,kind}',
                    'model',jsonb_build_array(jsonb_build_object('role','assistant','content',
                      jsonb_agg(jsonb_build_object('type','toolCall','id',p.part->'id','name',p.part->'name') ORDER BY m.i,p.j)))))
                FROM jsonb_array_elements(CASE jsonb_typeof(items.w#>'{value,model}') WHEN 'array' THEN items.w#>'{value,model}' ELSE '[]'::jsonb END) WITH ORDINALITY AS m(msg,i)
                CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN m.msg->>'role'='assistant' AND jsonb_typeof(m.msg->'content')='array' THEN m.msg->'content' ELSE '[]'::jsonb END) WITH ORDINALITY AS p(part,j)
                WHERE p.part->>'type'='toolCall'
                HAVING count(*)>0)
              ELSE items.w
            END AS write
            FROM jsonb_array_elements(d.writes) WITH ORDINALITY AS items(w,n)
            WHERE items.w->>'type' IN ('conversation','task','submission','entry')
          ) kept
          WHERE kept.write IS NOT NULL
        ),'[]'::jsonb) AS writes
      FROM public.agent_durable_commits d
      WHERE d.run_id=p_run_id AND d.sequence>p_after
      ORDER BY d.sequence
      LIMIT 200
    ) c;
  RETURN result;
END;
$$;
SET default_tablespace = '';
SET default_table_access_method = heap;

-- Name: agent_cache_tool(uuid, text, bigint, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_cache_tool(p_run_id uuid, p_worker_id text, p_fence bigint, p_call_id text, p_tool_name text, p_kind text, p_args jsonb, p_result jsonb) RETURNS public.agent_run_artifacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE a public.agent_run_artifacts;
BEGIN
  PERFORM public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  INSERT INTO public.agent_run_artifacts(run_id,call_id,tool_name,kind,args,result)
    VALUES(p_run_id,p_call_id,p_tool_name,p_kind,p_args,p_result) ON CONFLICT(run_id,call_id) DO NOTHING;
  SELECT * INTO STRICT a FROM public.agent_run_artifacts WHERE run_id=p_run_id AND call_id=p_call_id;
  IF a.tool_name<>p_tool_name OR a.args IS DISTINCT FROM p_args OR a.kind<>p_kind THEN RAISE EXCEPTION 'AGENT_TOOL_CALL_MISMATCH'; END IF;
  RETURN a;
END;
$$;

-- Name: agent_cancel_pending_commands(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_cancel_pending_commands() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.cancel_requested OR NEW.status IN ('cancelled','failed') THEN
    UPDATE public.agent_run_commands SET consumed=true,delivery_state='cancelled',revision=revision+1 WHERE run_id=NEW.id AND (delivery_state='pending' OR (NEW.status IN ('cancelled','failed') AND delivery_state='claimed' AND NOT durable_admitted));
  END IF;
  RETURN NEW;
END;
$$;

-- Name: agent_cancel_run(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_cancel_run(p_run_id uuid) RETURNS public.agent_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.agent_runs;
BEGIN
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id FOR UPDATE;
  IF NOT FOUND OR (r.user_id IS DISTINCT FROM auth.uid() AND NOT coalesce(public.is_admin_user(),false) AND coalesce(auth.role(),'')<>'service_role') THEN RAISE EXCEPTION 'AGENT_RUN_NOT_FOUND' USING ERRCODE='42501'; END IF;
  IF r.status IN ('completed','failed','cancelled') THEN RETURN r; END IF;
  UPDATE public.agent_runs SET cancel_requested=true,status=CASE WHEN status IN ('queued','awaiting_input') THEN 'queued' ELSE 'cancelling' END WHERE id=p_run_id RETURNING * INTO r;
  PERFORM public.agent_emit(p_run_id,'cancel_requested');
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id;
  RETURN r;
END;
$$;

-- Name: agent_change_command(uuid, bigint, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_change_command(p_run_id uuid, p_sequence bigint, p_revision integer, p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS public.agent_run_commands
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.agent_runs; cmd public.agent_run_commands;
BEGIN
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id FOR UPDATE;
  IF NOT FOUND OR r.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'AGENT_RUN_NOT_FOUND' USING ERRCODE='42501'; END IF;
  SELECT * INTO cmd FROM public.agent_run_commands WHERE run_id=p_run_id AND sequence=p_sequence FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AGENT_COMMAND_NOT_FOUND'; END IF;
  IF cmd.delivery_state<>'pending' OR cmd.revision<>p_revision OR r.cancel_requested OR r.status NOT IN ('queued','running','awaiting_input') THEN RAISE EXCEPTION 'AGENT_COMMAND_LOCKED' USING ERRCODE='40001'; END IF;
  IF p_action='edit' THEN
    IF coalesce(btrim(p_payload->>'content'),'')='' OR length(p_payload->>'content')>32000 THEN RAISE EXCEPTION 'AGENT_INVALID_MESSAGE'; END IF;
    cmd.message:=jsonb_set(cmd.message,'{content}',to_jsonb(p_payload->>'content'));
  ELSIF p_action='withdraw' THEN cmd.delivery_state:='cancelled'; cmd.consumed:=true;
  ELSIF p_action='order' THEN
    IF jsonb_typeof(p_payload->'sortOrder')<>'number' OR abs((p_payload->>'sortOrder')::numeric)>9007199254740991 THEN RAISE EXCEPTION 'AGENT_INVALID_ORDER'; END IF;
    cmd.sort_order:=(p_payload->>'sortOrder')::bigint;
  ELSIF p_action='promote' THEN
    IF cmd.mode='reply' THEN RAISE EXCEPTION 'AGENT_QUESTION_REPLY_LOCKED'; END IF;
    cmd.mode:='steer'; SELECT coalesce(min(sort_order),0)-1024 INTO cmd.sort_order FROM public.agent_run_commands WHERE run_id=p_run_id;
  ELSE RAISE EXCEPTION 'AGENT_INVALID_ACTION'; END IF;
  UPDATE public.agent_run_commands SET message=cmd.message,mode=cmd.mode,delivery_state=cmd.delivery_state,consumed=cmd.consumed,sort_order=cmd.sort_order,revision=revision+1 WHERE sequence=p_sequence RETURNING * INTO cmd;
  PERFORM public.agent_emit(p_run_id,'queue_changed');
  RETURN cmd;
END;
$$;

-- Name: agent_checkpoint(uuid, text, bigint, jsonb, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_checkpoint(p_run_id uuid, p_worker_id text, p_fence bigint, p_checkpoint jsonb, p_message jsonb, p_event jsonb, p_command bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  UPDATE public.agent_runs SET checkpoint=p_checkpoint,public_message=p_message,updated_at=now() WHERE id=p_run_id;
  IF p_command IS NOT NULL THEN UPDATE public.agent_run_commands SET consumed=true WHERE run_id=p_run_id AND sequence=p_command; END IF;
  PERFORM public.agent_emit(p_run_id,coalesce(p_event->>'type','checkpoint'),p_event);
END;
$$;

-- Name: agent_claim_command(uuid, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_claim_command(p_run_id uuid, p_worker_id text, p_fence bigint, p_sequence bigint) RETURNS public.agent_run_commands
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.agent_runs; cmd public.agent_run_commands; messages jsonb; previous_write text;
BEGIN
  r:=public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF r.cancel_requested THEN RETURN NULL; END IF;
  SELECT * INTO cmd FROM public.agent_run_commands WHERE run_id=p_run_id AND sequence=p_sequence FOR UPDATE;
  IF NOT FOUND OR cmd.delivery_state NOT IN ('pending','claimed') THEN RETURN NULL; END IF;
  IF cmd.delivery_state='pending' THEN UPDATE public.agent_run_commands SET delivery_state='claimed',revision=revision+1 WHERE sequence=p_sequence RETURNING * INTO cmd; END IF;
  SELECT coalesce(c.messages,'[]') INTO messages FROM public.conversations c WHERE c.id=r.conversation_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(messages) m WHERE m->>'id'=cmd.message->>'id') THEN
    previous_write:=current_setting('taibu.agent_write',true); PERFORM set_config('taibu.agent_write','true',true);
    PERFORM public.replace_conversation_messages(r.conversation_id,messages||jsonb_build_array(cmd.message));
    PERFORM set_config('taibu.agent_write',coalesce(previous_write,''),true);
  END IF;
  PERFORM public.agent_emit(p_run_id,'command_claimed');
  RETURN cmd;
END;
$$;

-- Name: agent_claim_run(text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_claim_run(p_worker_id text) RETURNS public.agent_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.agent_runs;
BEGIN
  PERFORM public.agent_require_admin();
  IF NOT EXISTS(SELECT 1 FROM public.agent_workers WHERE id=p_worker_id AND engine='pi-durable/1.3.0') THEN RETURN NULL; END IF;
  SELECT * INTO r FROM public.agent_runs
    WHERE (status='queued' OR (status IN ('running','cancelling') AND lease_until<now()))
      AND checkpoint->>'version'='2' AND checkpoint#>>'{durable,engine}'='pi-durable/1.3.0'
    ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.agent_runs SET status=CASE WHEN cancel_requested THEN 'cancelling' ELSE 'running' END,
    worker_id=p_worker_id,fence=fence+1,lease_until=now()+interval '60 seconds',updated_at=now()
    WHERE id=r.id RETURNING * INTO r;
  PERFORM public.agent_emit(r.id,'claimed');
  SELECT * INTO r FROM public.agent_runs WHERE id=r.id;
  RETURN r;
END;
$$;

-- Name: agent_command_delivery_state(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_command_delivery_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.delivery_state<>'cancelled' THEN
    IF NEW.consumed THEN NEW.delivery_state:='consumed'; ELSIF NEW.durable_admitted THEN NEW.delivery_state:='admitted'; END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- Name: agent_create_run(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_create_run(p_id uuid, p_user_id uuid, p_conversation_id uuid, p_request_id text, p_request_hash text, p_input jsonb, p_checkpoint jsonb, p_message jsonb, p_credential jsonb, p_charge boolean) RETURNS public.agent_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r public.agent_runs; c public.conversations; balance integer; messages jsonb;
  anchor_position bigint; anchor_message jsonb; old_answer jsonb; versions jsonb;
  version_index integer; version_snapshot jsonb; tail_position bigint; previous_write text;
BEGIN
  PERFORM public.agent_require_admin();
  IF coalesce(p_checkpoint->>'version','')<>'2' OR coalesce(p_checkpoint#>>'{durable,engine}','')<>'pi-durable/1.3.0' THEN RAISE EXCEPTION 'AGENT_ENGINE_UNSUPPORTED' USING ERRCODE='22023'; END IF;
  SELECT * INTO c FROM public.conversations WHERE id=p_conversation_id FOR UPDATE;
  IF NOT FOUND OR c.user_id IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'AGENT_CONVERSATION_NOT_FOUND' USING ERRCODE='42501'; END IF;
  SELECT * INTO r FROM public.agent_runs WHERE user_id=p_user_id AND request_id=p_request_id;
  IF FOUND THEN
    IF r.request_hash<>p_request_hash THEN RAISE EXCEPTION 'AGENT_REQUEST_MISMATCH' USING ERRCODE='22023'; END IF;
    RETURN r;
  END IF;
  IF EXISTS(SELECT 1 FROM public.agent_runs WHERE conversation_id=p_conversation_id AND status IN ('queued','running','awaiting_input','cancelling')) THEN
    RAISE EXCEPTION 'AGENT_CONVERSATION_BUSY' USING ERRCODE='23505';
  END IF;
  IF p_charge THEN
    balance:=public.decrement_ai_chat_count(p_user_id);
    IF balance IS NULL THEN RAISE EXCEPTION 'INSUFFICIENT_CREDITS' USING ERRCODE='P0001'; END IF;
  END IF;
  INSERT INTO public.agent_runs(id,user_id,conversation_id,request_id,request_hash,input,checkpoint,public_message,billing)
    VALUES(p_id,p_user_id,p_conversation_id,p_request_id,p_request_hash,p_input,p_checkpoint,p_message,CASE WHEN p_charge THEN 'charged' ELSE 'exempt' END) RETURNING * INTO r;
  IF p_credential IS NOT NULL THEN INSERT INTO public.agent_run_credentials VALUES(p_id,p_credential); END IF;
  messages:=coalesce(c.messages,'[]');
  IF p_input->>'replaceFromMessageId' IS NOT NULL THEN
    SELECT n INTO anchor_position FROM jsonb_array_elements(messages) WITH ORDINALITY t(m,n) WHERE m->>'id'=p_input->>'replaceFromMessageId' AND m->>'role'='user';
    IF anchor_position IS NULL THEN RAISE EXCEPTION 'AGENT_EDIT_ANCHOR_NOT_FOUND'; END IF;
    anchor_message:=messages->(anchor_position::integer-1);
    old_answer:=messages->anchor_position::integer;
    tail_position:=anchor_position;
    IF old_answer->>'role'='assistant' THEN tail_position:=anchor_position+1; ELSE old_answer:=NULL; END IF;
    versions:=CASE WHEN jsonb_typeof(anchor_message->'versions')='array' THEN anchor_message->'versions' ELSE '[]'::jsonb END;
    version_index:=jsonb_array_length(versions)-1;
    IF coalesce(anchor_message->>'currentVersionIndex','') ~ '^[0-9]{1,9}$' THEN
      IF (anchor_message->>'currentVersionIndex')::integer < jsonb_array_length(versions) THEN
        version_index:=(anchor_message->>'currentVersionIndex')::integer;
      END IF;
    END IF;
    version_snapshot:=CASE WHEN jsonb_typeof(versions->version_index)='object' THEN versions->version_index ELSE '{}'::jsonb END;
    version_snapshot:=version_snapshot||jsonb_build_object(
      'userContent',anchor_message->>'content','attachments',anchor_message->'attachments','mentions',anchor_message->'mentions',
      'aiContent',coalesce(old_answer->>'content',''),'aiAgent',old_answer->'agent','aiMetadata',old_answer->'metadata',
      'createdAt',coalesce(old_answer->>'createdAt',anchor_message->>'createdAt'),
      'subsequentMessages',coalesce((SELECT jsonb_agg(m ORDER BY n) FROM jsonb_array_elements(messages) WITH ORDINALITY t(m,n) WHERE n>tail_position),'[]'));
    IF version_index<0 THEN
      versions:=jsonb_build_array(version_snapshot); version_index:=0;
    ELSE
      versions:=jsonb_set(versions,ARRAY[version_index::text],version_snapshot);
    END IF;
    p_input:=jsonb_set(p_input,'{userMessage}',(p_input->'userMessage')||jsonb_build_object('versions',versions,'currentVersionIndex',version_index));
    UPDATE public.agent_runs SET input=p_input WHERE id=p_id;
    SELECT coalesce(jsonb_agg(m ORDER BY n),'[]') INTO messages FROM jsonb_array_elements(messages) WITH ORDINALITY t(m,n) WHERE n<anchor_position;
  END IF;
  messages:=messages||jsonb_build_array(p_input->'userMessage',p_message);
  previous_write:=current_setting('taibu.agent_write',true);
  PERFORM set_config('taibu.agent_write','true',true);
  PERFORM public.replace_conversation_messages(p_conversation_id,messages);
  PERFORM set_config('taibu.agent_write',coalesce(previous_write,''),true);
  PERFORM public.agent_emit(p_id,'queued');
  SELECT * INTO r FROM public.agent_runs WHERE id=p_id;
  RETURN r;
END;
$_$;

-- Name: agent_durable_commit(uuid, text, bigint, bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_durable_commit(p_run_id uuid, p_worker_id text, p_fence bigint, p_sequence bigint, p_writes jsonb, p_checkpoint jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE existing jsonb; previous bigint; w jsonb; command_sequence bigint;
BEGIN
  PERFORM public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF p_sequence<1 OR jsonb_typeof(p_writes) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'AGENT_DURABLE_COMMIT_INVALID' USING ERRCODE='22023';
  END IF;
  SELECT writes INTO existing FROM public.agent_durable_commits WHERE run_id=p_run_id AND sequence=p_sequence;
  IF FOUND THEN
    IF existing IS DISTINCT FROM p_writes THEN RAISE EXCEPTION 'AGENT_DURABLE_CONFLICT' USING ERRCODE='40001'; END IF;
    RETURN p_sequence;
  END IF;
  SELECT coalesce(max(sequence),0) INTO previous FROM public.agent_durable_commits WHERE run_id=p_run_id;
  IF p_sequence<>previous+1 THEN RAISE EXCEPTION 'AGENT_DURABLE_CONFLICT' USING ERRCODE='40001'; END IF;
  INSERT INTO public.agent_durable_commits(run_id,sequence,writes) VALUES(p_run_id,p_sequence,p_writes);
  UPDATE public.agent_runs SET checkpoint=p_checkpoint,updated_at=now() WHERE id=p_run_id;
  -- Admission alone is not consumption. Pi records a placed submission before
  -- advancing its model task; acknowledge the matching outer command atomically.
  FOR w IN SELECT value FROM jsonb_array_elements(p_writes) LOOP
    IF w->>'type'='submission'
      AND w#>>'{value,requestId}' ~ '^command:[0-9]+$' THEN
      command_sequence:=substring(w#>>'{value,requestId}' FROM 9)::bigint;
      UPDATE public.agent_run_commands SET durable_admitted=true,
        consumed=consumed OR w#>>'{value,status}' IN ('placed','done')
        WHERE run_id=p_run_id AND sequence=command_sequence;
    END IF;
  END LOOP;
  RETURN p_sequence;
END;
$_$;

-- Name: agent_durable_read(uuid, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_durable_read(p_run_id uuid, p_worker_id text, p_fence bigint, p_after bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF p_after<0 THEN RAISE EXCEPTION 'AGENT_DURABLE_CURSOR_INVALID' USING ERRCODE='22023'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sequence',c.sequence,'writes',c.writes) ORDER BY c.sequence),'[]')
    INTO result FROM (SELECT sequence,writes FROM public.agent_durable_commits
      WHERE run_id=p_run_id AND sequence>p_after ORDER BY sequence LIMIT 200) c;
  RETURN result;
END;
$$;

-- Name: agent_emit(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_emit(p_run_id uuid, p_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE cursor_value bigint;
BEGIN
  INSERT INTO public.agent_run_events(run_id,type,payload) VALUES(p_run_id,p_type,p_payload) RETURNING sequence INTO cursor_value;
  UPDATE public.agent_runs SET event_cursor=cursor_value WHERE id=p_run_id;
END;
$$;

-- Name: agent_finish_run(uuid, text, bigint, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_finish_run(p_run_id uuid, p_worker_id text, p_fence bigint, p_status text, p_checkpoint jsonb, p_message jsonb) RETURNS public.agent_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.agent_runs; final_status text;
BEGIN
  r:=public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF p_status NOT IN ('completed','awaiting_input','failed','cancelled') THEN RAISE EXCEPTION 'AGENT_INVALID_STATUS'; END IF;
  final_status:=CASE WHEN r.cancel_requested THEN 'cancelled' ELSE p_status END;
  IF final_status IN ('completed','awaiting_input') AND EXISTS(SELECT 1 FROM public.agent_run_commands WHERE run_id=p_run_id AND NOT consumed AND (final_status<>'awaiting_input' OR (mode='reply' AND NOT durable_admitted))) THEN
    final_status:='queued';
  END IF;
  IF final_status IN ('failed','cancelled') AND r.billing='charged' AND coalesce(btrim(p_message->>'content'),'')='' AND r.record_id IS NULL THEN
    IF public.increment_ai_chat_count(r.user_id,1) IS NULL THEN RAISE EXCEPTION 'AGENT_REFUND_FAILED'; END IF;
    r.billing:='refunded';
  END IF;
  p_message:=jsonb_set(p_message,'{agent,status}',to_jsonb(final_status));
  UPDATE public.agent_runs SET status=final_status,checkpoint=p_checkpoint,public_message=p_message,billing=r.billing,
    lease_until=NULL,worker_id=NULL,updated_at=now() WHERE id=p_run_id RETURNING * INTO r;
  IF final_status IN ('completed','failed','cancelled') THEN DELETE FROM public.agent_run_credentials WHERE run_id=p_run_id; END IF;
  PERFORM public.agent_emit(p_run_id,final_status);
  PERFORM public.agent_sync_message(p_run_id);
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id;
  RETURN r;
END;
$$;

-- Name: agent_memory_guard(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_memory_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN PERFORM public.agent_require_admin(); END IF;
  IF NEW.source_run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.agent_runs WHERE id=NEW.source_run_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'AGENT_MEMORY_SOURCE_OWNER'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,910));
  IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.user_agent_memory WHERE user_id=NEW.user_id AND fingerprint=md5(NEW.content)) AND (SELECT count(*) FROM public.user_agent_memory WHERE user_id=NEW.user_id)>=128 THEN RAISE EXCEPTION 'AGENT_MEMORY_LIMIT'; END IF;
  NEW.updated_at:=now(); RETURN NEW;
END;
$$;

-- Name: agent_notify_command(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_notify_command() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform pg_notify('taibu_agent', json_build_object(
    't', 'cmd',
    'run', NEW.run_id
  )::text);
  return NEW;
end;
$$;

-- Name: agent_notify_event(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.agent_notify_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform pg_notify('taibu_agent', json_build_object(
