                EXIT;
            END IF;
        END LOOP;
        IF v_has_invalid_elem THEN
            v_skipped := v_skipped + 1;
            v_errors := v_errors || jsonb_build_object(
                'id', v_entry_id,
                'reason', 'invalid_element',
