-- Name: check_vector_index_exists(integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.check_vector_index_exists(p_dim integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from pg_indexes
    where schemaname = 'public'
      and (
        (p_dim is not null and indexname = 'knowledge_entries_vector_' || p_dim || '_hnsw_idx')
        or (p_dim is null and indexname like 'knowledge_entries_vector_%_hnsw_idx')
      )
  );
$$;

-- Name: claim_agent_attachment_cleanup(integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.claim_agent_attachment_cleanup(p_limit integer DEFAULT 50) RETURNS SETOF public.agent_attachments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 PERFORM public.agent_require_admin();
 RETURN QUERY UPDATE public.agent_attachments SET status='deleting' WHERE id IN (
   SELECT a.id FROM public.agent_attachments a WHERE (a.status='deleting' OR a.orphaned_at<now()-interval '24 hours') AND NOT EXISTS(SELECT 1 FROM public.agent_attachment_refs r WHERE r.attachment_id=a.id)
   ORDER BY a.created_at LIMIT least(greatest(p_limit,1),100) FOR UPDATE SKIP LOCKED
 ) RETURNING *;
END;
$$;

-- Name: claim_daily_briefings(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.claim_daily_briefings(p_limit integer DEFAULT 2, p_enabled boolean DEFAULT true) RETURNS SETOF public.daily_briefing_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE job public.daily_briefing_jobs; balance integer; local_now timestamp; item record;
BEGIN
 PERFORM public.agent_require_admin();
 -- Cancel expired or disabled work. Row locks and billing state fence each refund.
 FOR job IN SELECT j.* FROM public.daily_briefing_jobs j WHERE j.status IN ('pending','generating') AND
 (NOT p_enabled OR j.deadline<=now() OR NOT EXISTS(SELECT 1 FROM public.reminder_subscriptions s WHERE s.user_id=j.user_id AND s.reminder_type='daily_briefing' AND s.enabled))
 ORDER BY j.created_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP
  IF job.billing='reserved' THEN PERFORM public.increment_ai_chat_count(job.user_id,1); END IF;
  UPDATE public.daily_briefing_jobs SET status='cancelled',billing=CASE WHEN billing='reserved' THEN 'refunded' ELSE billing END,lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=job.id;
 END LOOP;
 IF NOT p_enabled THEN RETURN; END IF;
 FOR item IN
  SELECT s.user_id,coalesce(tz.name,'Asia/Shanghai') AS zone,
    CASE WHEN u.daily_briefing_settings->>'time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN (u.daily_briefing_settings->>'time')::time ELSE time '08:00' END AS delivery_time
  FROM public.reminder_subscriptions s LEFT JOIN public.user_settings u ON u.user_id=s.user_id
  LEFT JOIN pg_timezone_names tz ON tz.name=coalesce(u.daily_briefing_settings->>'timezone','Asia/Shanghai')
  WHERE s.reminder_type='daily_briefing' AND s.enabled AND
    (now() AT TIME ZONE coalesce(tz.name,'Asia/Shanghai'))::time >= CASE WHEN u.daily_briefing_settings->>'time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN (u.daily_briefing_settings->>'time')::time ELSE time '08:00' END
    AND NOT EXISTS(SELECT 1 FROM public.daily_briefing_jobs j WHERE j.user_id=s.user_id AND j.local_date=(now() AT TIME ZONE coalesce(tz.name,'Asia/Shanghai'))::date)
  ORDER BY s.user_id LIMIT least(greatest(p_limit,1),10)
 LOOP
  local_now:=now() AT TIME ZONE item.zone;
  INSERT INTO public.daily_briefing_jobs(user_id,local_date,timezone,deadline) VALUES(item.user_id,local_now::date,item.zone,((local_now::date+1)::timestamp AT TIME ZONE item.zone)) ON CONFLICT(user_id,local_date) DO NOTHING;
 END LOOP;
 FOR job IN SELECT j.* FROM public.daily_briefing_jobs j WHERE j.deadline>now() AND
 (j.status='pending' OR (j.status='generating' AND j.lease_until<now()))
 ORDER BY j.created_at LIMIT least(greatest(p_limit,1),10) FOR UPDATE SKIP LOCKED LOOP
  IF job.attempts>=3 THEN
   IF job.billing='reserved' THEN PERFORM public.increment_ai_chat_count(job.user_id,1); END IF;
   UPDATE public.daily_briefing_jobs SET status='failed',billing=CASE WHEN billing='reserved' THEN 'refunded' ELSE billing END,lease_token=NULL,lease_until=NULL,error='生成重试耗尽',updated_at=now() WHERE id=job.id;
   CONTINUE;
  END IF;
  IF job.billing='none' THEN
   balance:=public.decrement_ai_chat_count(job.user_id);
   IF balance IS NULL THEN UPDATE public.daily_briefing_jobs SET status='skipped',error='余额不足',updated_at=now() WHERE id=job.id; CONTINUE; END IF;
  END IF;
  UPDATE public.daily_briefing_jobs SET status='generating',billing='reserved',attempts=attempts+1,lease_token=gen_random_uuid(),lease_until=now()+interval '3 minutes',updated_at=now() WHERE id=job.id RETURNING * INTO job;
  RETURN NEXT job;
 END LOOP;
END;
$_$;

-- Name: claim_linuxdo_membership_as_service(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.claim_linuxdo_membership_as_service(p_user_id uuid, p_plan_id text, p_trust_level integer, p_provider_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_last_claim_at timestamptz;
  v_current_membership text;
  v_current_membership_expires_at timestamptz;
  v_effective_membership text := 'free';
  v_next_expires_at timestamptz;
  v_now timestamptz := now();
BEGIN
IF auth.role() <> 'service_role' THEN
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
END IF;
  IF p_plan_id NOT IN ('plus', 'pro') THEN
    RETURN jsonb_build_object('status', 'invalid_plan');
  END IF;
  -- Serialize per-user monthly claims so the cooldown check and grant write
  -- happen inside the same critical section.
  PERFORM pg_advisory_xact_lock(hashtextextended('linuxdo_monthly_claim:' || p_user_id::text, 0));
  SELECT used_at
  INTO v_last_claim_at
  FROM public.activation_keys
  WHERE used_by = p_user_id
    AND key_type = 'membership'
    AND source = 'linuxdo_monthly'
  ORDER BY used_at DESC
  LIMIT 1;
  IF v_last_claim_at IS NOT NULL AND v_last_claim_at > v_now - INTERVAL '30 days' THEN
    RETURN jsonb_build_object(
      'status', 'cooldown',
      'next_available_at', v_last_claim_at + INTERVAL '30 days'
    );
  END IF;
  SELECT membership, membership_expires_at
  INTO v_current_membership, v_current_membership_expires_at
  FROM public.users
  WHERE id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'user_not_found');
  END IF;
  IF v_current_membership IN ('plus', 'pro')
    AND v_current_membership_expires_at IS NOT NULL
    AND v_current_membership_expires_at > v_now THEN
    v_effective_membership := v_current_membership;
  END IF;
  IF public.membership_rank(v_effective_membership) > public.membership_rank(p_plan_id) THEN
    RETURN jsonb_build_object(
      'status', 'lower_tier_ignored',
      'membership', v_effective_membership,
      'expires_at', v_current_membership_expires_at
    );
  END IF;
  IF public.membership_rank(v_effective_membership) = public.membership_rank(p_plan_id)
    AND v_effective_membership <> 'free'
    AND v_current_membership_expires_at IS NOT NULL
    AND v_current_membership_expires_at > v_now THEN
    v_next_expires_at := v_current_membership_expires_at + INTERVAL '30 days';
  ELSE
    v_next_expires_at := v_now + INTERVAL '30 days';
  END IF;
  INSERT INTO public.activation_keys (
    key_code,
    key_type,
    membership_type,
    is_used,
    used_by,
    used_at,
    created_by,
    source,
    metadata
  )
  VALUES (
    'sk-auto-' || replace(gen_random_uuid()::text, '-', ''),
    'membership',
    p_plan_id,
    true,
    p_user_id,
    v_now,
    p_user_id,
    'linuxdo_monthly',
    jsonb_build_object(
      'trust_level', p_trust_level,
      'provider_user_id', p_provider_user_id
    )
  );
  UPDATE public.users
  SET
    membership = p_plan_id,
    membership_expires_at = v_next_expires_at,
    updated_at = now()
  WHERE id = p_user_id;
  RETURN jsonb_build_object(
    'status', 'ok',
    'membership', p_plan_id,
    'expires_at', v_next_expires_at
  );
END;
$$;

-- Name: claim_notification_popup(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.claim_notification_popup(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE affected integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  UPDATE public.notifications SET popup_claimed_at=now() WHERE id=p_id AND user_id=auth.uid() AND NOT is_read AND popup_claimed_at IS NULL AND event_key IS NOT NULL;
  GET DIAGNOSTICS affected=ROW_COUNT; RETURN affected=1;
END;
$$;

-- Name: claim_prompt_enhancement(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.claim_prompt_enhancement() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE affected integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  INSERT INTO public.prompt_enhancement_usage(user_id,local_date,calls) VALUES(auth.uid(),(now() AT TIME ZONE 'Asia/Shanghai')::date,1)
  ON CONFLICT(user_id,local_date) DO UPDATE SET calls=prompt_enhancement_usage.calls+1 WHERE prompt_enhancement_usage.calls<5;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected=1;
END;
$$;

-- Name: cleanup_expired_identity_rows(integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.cleanup_expired_identity_rows(p_limit integer DEFAULT 5000) RETURNS TABLE(sessions_deleted bigint, verifications_deleted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_temp'
    AS $$
declare
  v_sessions bigint;
  v_verifications bigint;
begin
  if not public.is_admin_user() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from identity.sessions
  where id in (
    select id from identity.sessions where expires_at < now() - interval '1 day' limit p_limit
  );
  get diagnostics v_sessions = row_count;
  delete from identity.verifications
  where id in (
    select id from identity.verifications where expires_at < now() - interval '1 day' limit p_limit
  );
  get diagnostics v_verifications = row_count;
  return query select v_sessions, v_verifications;
end;
$$;

-- Name: create_analysis_conversation_with_history_as_service(uuid, text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.create_analysis_conversation_with_history_as_service(p_user_id uuid, p_source_type text, p_source_data jsonb, p_title text, p_personality text, p_messages jsonb, p_history_type text, p_history_payload jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_conversation_id uuid;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_history_type NOT IN ('meihua', 'xiaoliuren') THEN
    RETURN public.create_analysis_conversation_with_history_legacy_as_service(
      p_user_id,
      p_source_type,
      p_source_data,
      p_title,
      p_personality,
      p_messages,
      p_history_type,
      p_history_payload
    );
  END IF;
  IF COALESCE(jsonb_typeof(p_messages), 'null') <> 'array' THEN
    RAISE EXCEPTION 'messages must be an array' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.conversations (
    user_id, source_type, source_data, title, personality, messages
  ) VALUES (
    p_user_id,
    p_source_type,
    COALESCE(p_source_data, '{}'::jsonb),
    p_title,
    COALESCE(NULLIF(p_personality, ''), 'general'),
    '[]'::jsonb
  ) RETURNING id INTO v_conversation_id;
  PERFORM public.replace_conversation_messages(v_conversation_id, p_messages);
  IF p_history_type = 'meihua' THEN
    UPDATE public.meihua_divinations
    SET conversation_id = v_conversation_id
    WHERE id::text = p_history_payload->>'divination_id'
      AND user_id = p_user_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'meihua divination not found';
    END IF;
  ELSE
    UPDATE public.xiaoliuren_divinations
    SET conversation_id = v_conversation_id
    WHERE id::text = p_history_payload->>'divination_id'
      AND user_id = p_user_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'xiaoliuren divination not found';
    END IF;
  END IF;
  RETURN v_conversation_id::text;
END;
$$;

-- Name: create_analysis_conversation_with_history_legacy_as_service(uuid, text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.create_analysis_conversation_with_history_legacy_as_service(p_user_id uuid, p_source_type text, p_source_data jsonb, p_title text, p_personality text, p_messages jsonb, p_history_type text, p_history_payload jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conversation_id uuid;
  v_yongshen_targets text[];
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(jsonb_typeof(p_messages), 'null') <> 'array' THEN
    RAISE EXCEPTION 'messages must be an array' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.conversations (
    user_id,
    source_type,
    source_data,
    title,
    personality,
    messages
  )
  VALUES (
    p_user_id,
    p_source_type,
    COALESCE(p_source_data, '{}'::jsonb),
    p_title,
    COALESCE(NULLIF(p_personality, ''), 'general'),
    '[]'::jsonb
  )
  RETURNING id
  INTO v_conversation_id;
  PERFORM public.replace_conversation_messages(v_conversation_id, p_messages);
  CASE p_history_type
    WHEN 'mbti' THEN
      IF NULLIF(p_history_payload->>'reading_id', '') IS NOT NULL THEN
        UPDATE public.mbti_readings
        SET conversation_id = v_conversation_id
        WHERE id::text = p_history_payload->>'reading_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'mbti reading not found';
        END IF;
      ELSE
        INSERT INTO public.mbti_readings (
          user_id,
          mbti_type,
          scores,
          percentages,
          conversation_id
        )
        VALUES (
          p_user_id,
          p_history_payload->>'mbti_type',
          p_history_payload->'scores',
          p_history_payload->'percentages',
          v_conversation_id
        );
      END IF;
    WHEN 'tarot' THEN
      IF NULLIF(p_history_payload->>'reading_id', '') IS NOT NULL THEN
        UPDATE public.tarot_readings
        SET
          conversation_id = v_conversation_id,
          metadata = CASE
            WHEN p_history_payload ? 'metadata'
              AND jsonb_typeof(p_history_payload->'metadata') <> 'null'
              THEN p_history_payload->'metadata'
            ELSE metadata
          END
        WHERE id::text = p_history_payload->>'reading_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'tarot reading not found';
        END IF;
      ELSE
        INSERT INTO public.tarot_readings (
          user_id,
          spread_id,
          question,
          cards,
          conversation_id,
          metadata
        )
        VALUES (
          p_user_id,
          p_history_payload->>'spread_id',
          NULLIF(p_history_payload->>'question', ''),
          COALESCE(p_history_payload->'cards', '[]'::jsonb),
          v_conversation_id,
          COALESCE(p_history_payload->'metadata', '{}'::jsonb)
        );
      END IF;
    WHEN 'hepan' THEN
      IF NULLIF(p_history_payload->>'chart_id', '') IS NOT NULL THEN
        UPDATE public.hepan_charts
        SET conversation_id = v_conversation_id
        WHERE id::text = p_history_payload->>'chart_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'hepan chart not found';
        END IF;
      ELSE
        INSERT INTO public.hepan_charts (
          user_id,
          type,
          person1_name,
          person1_birth,
          person2_name,
          person2_birth,
          compatibility_score,
          conversation_id,
          result_data
        )
        VALUES (
          p_user_id,
          p_history_payload->>'type',
          p_history_payload->>'person1_name',
          COALESCE(p_history_payload->'person1_birth', '{}'::jsonb),
          p_history_payload->>'person2_name',
          COALESCE(p_history_payload->'person2_birth', '{}'::jsonb),
          CASE
            WHEN p_history_payload ? 'compatibility_score'
              THEN (p_history_payload->>'compatibility_score')::integer
            ELSE NULL
          END,
          v_conversation_id,
          p_history_payload->'result_data'
        );
      END IF;
    WHEN 'palm' THEN
      INSERT INTO public.palm_readings (
        user_id,
        analysis_type,
        hand_type,
        conversation_id
      )
      VALUES (
        p_user_id,
        COALESCE(NULLIF(p_history_payload->>'analysis_type', ''), 'full'),
        COALESCE(NULLIF(p_history_payload->>'hand_type', ''), 'left'),
        v_conversation_id
      );
    WHEN 'face' THEN
      INSERT INTO public.face_readings (
        user_id,
        analysis_type,
        conversation_id
      )
      VALUES (
        p_user_id,
        COALESCE(NULLIF(p_history_payload->>'analysis_type', ''), 'full'),
        v_conversation_id
      );
    WHEN 'qimen' THEN
      IF NULLIF(p_history_payload->>'chart_id', '') IS NOT NULL THEN
        UPDATE public.qimen_charts
        SET conversation_id = v_conversation_id
        WHERE id::text = p_history_payload->>'chart_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'qimen chart not found';
        END IF;
      ELSE
        INSERT INTO public.qimen_charts (
          user_id,
          question,
          chart_time,
          year,
          month,
          day,
          hour,
          minute,
          timezone,
          dun_type,
          ju_number,
          pan_type,
          ju_method,
          zhi_fu_ji_gong,
          conversation_id
        )
        VALUES (
          p_user_id,
          NULLIF(p_history_payload->>'question', ''),
          (p_history_payload->>'chart_time')::timestamptz,
          (p_history_payload->>'year')::integer,
          (p_history_payload->>'month')::integer,
          (p_history_payload->>'day')::integer,
          (p_history_payload->>'hour')::integer,
          (p_history_payload->>'minute')::integer,
          p_history_payload->>'timezone',
          p_history_payload->>'dun_type',
          (p_history_payload->>'ju_number')::integer,
          p_history_payload->>'pan_type',
          p_history_payload->>'ju_method',
          p_history_payload->>'zhi_fu_ji_gong',
          v_conversation_id
        );
      END IF;
    WHEN 'daliuren' THEN
      IF NULLIF(p_history_payload->>'divination_id', '') IS NOT NULL THEN
        UPDATE public.daliuren_divinations
        SET conversation_id = v_conversation_id
        WHERE id::text = p_history_payload->>'divination_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'daliuren divination not found';
        END IF;
      END IF;
    WHEN 'liuyao' THEN
      v_yongshen_targets := ARRAY(
        SELECT jsonb_array_elements_text(COALESCE(p_history_payload->'yongshen_targets', '[]'::jsonb))
      );
      IF NULLIF(p_history_payload->>'divination_id', '') IS NOT NULL THEN
        UPDATE public.liuyao_divinations
        SET
          conversation_id = v_conversation_id,
          yongshen_targets = CASE
            WHEN array_length(v_yongshen_targets, 1) IS NULL THEN NULL
            ELSE v_yongshen_targets
          END
        WHERE id::text = p_history_payload->>'divination_id'
          AND user_id = p_user_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'liuyao divination not found';
        END IF;
      ELSE
        INSERT INTO public.liuyao_divinations (
          user_id,
          question,
          yongshen_targets,
          hexagram_code,
          changed_hexagram_code,
          changed_lines,
          conversation_id
        )
        VALUES (
          p_user_id,
          COALESCE(p_history_payload->>'question', ''),
          CASE
            WHEN array_length(v_yongshen_targets, 1) IS NULL THEN NULL
            ELSE v_yongshen_targets
          END,
          p_history_payload->>'hexagram_code',
          NULLIF(p_history_payload->>'changed_hexagram_code', ''),
          p_history_payload->'changed_lines',
          v_conversation_id
        );
      END IF;
    ELSE
      RAISE EXCEPTION 'invalid history type' USING ERRCODE = '22023';
  END CASE;
  RETURN v_conversation_id::text;
END;
$$;

-- Name: create_conversation_with_messages(uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.create_conversation_with_messages(p_user_id uuid, p_title text, p_personality text DEFAULT NULL::text, p_source_type text DEFAULT NULL::text, p_source_data jsonb DEFAULT NULL::jsonb, p_messages jsonb DEFAULT '[]'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_conversation_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_admin_user() AND v_actor_id <> p_user_id THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(jsonb_typeof(p_messages), 'null') <> 'array' THEN
    RAISE EXCEPTION 'messages must be an array' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.conversations (
    user_id,
    title,
    personality,
    source_type,
    source_data,
    messages
  )
  VALUES (
    p_user_id,
    COALESCE(NULLIF(p_title, ''), '新对话'),
    COALESCE(NULLIF(p_personality, ''), 'general'),
    p_source_type,
    p_source_data,
    '[]'::jsonb
  )
  RETURNING id
  INTO v_conversation_id;
  PERFORM public.replace_conversation_messages(v_conversation_id, COALESCE(p_messages, '[]'::jsonb));
  RETURN v_conversation_id::text;
END;
$$;

-- Name: create_knowledge_base_with_limit(uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.create_knowledge_base_with_limit(p_user_id uuid, p_name text, p_description text DEFAULT NULL::text, p_weight text DEFAULT 'normal'::text, p_limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_count integer;
  v_kb public.knowledge_bases;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_limit <= 0 THEN
    RAISE EXCEPTION 'invalid limit' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(format('knowledge-base:%s', p_user_id), 0));
  SELECT COUNT(*)
  INTO v_existing_count
  FROM public.knowledge_bases
  WHERE user_id = p_user_id;
  IF v_existing_count >= p_limit THEN
    RETURN jsonb_build_object('status', 'limit_reached');
  END IF;
  INSERT INTO public.knowledge_bases (
    user_id,
    name,
    description,
    weight
  )
  VALUES (
    p_user_id,
    p_name,
    p_description,
    p_weight
  )
  RETURNING *
  INTO v_kb;
  RETURN jsonb_build_object(
    'status', 'ok',
    'knowledge_base', to_jsonb(v_kb)
  );
END;
$$;

-- Name: decrement_ai_chat_count(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.decrement_ai_chat_count(user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_count integer;
BEGIN
IF auth.role() <> 'service_role' THEN
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
END IF;
  UPDATE public.users
  SET
    ai_chat_count = GREATEST(COALESCE(ai_chat_count, 0) - 1, 0),
    updated_at = now()
  WHERE id = user_id
    AND COALESCE(ai_chat_count, 0) > 0
  RETURNING ai_chat_count INTO new_count;
  IF new_count IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM public.record_credit_transaction(
    user_id,
    -1,
    'spend',
    'ai_usage',
    new_count,
    'credit_usage',
    NULL,
    'AI 使用消费 1 积分',
    '{}'::jsonb
  );
  RETURN new_count;
END;
$$;

-- Name: delete_agent_retention(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.delete_agent_retention(p_event_days integer DEFAULT 30, p_commit_days integer DEFAULT 7, p_worker_hours integer DEFAULT 24, p_limit integer DEFAULT 1000) RETURNS TABLE(events_deleted bigint, commits_deleted bigint, workers_deleted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_events bigint;
  v_commits bigint;
  v_workers bigint;
begin
  if not public.is_admin_user() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_event_days < 7 or p_commit_days < 1 or p_worker_hours < 1 or p_limit < 1 or p_limit > 10000 then
    raise exception 'invalid retention bounds' using errcode = '22023';
  end if;
  delete from public.agent_run_events
  where run_id in (
    select id from public.agent_runs
    where status in ('completed', 'failed', 'cancelled')
      and updated_at < now() - make_interval(days => p_event_days)
    limit p_limit
  );
  get diagnostics v_events = row_count;
  delete from public.agent_durable_commits
  where run_id in (
    select id from public.agent_runs
    where status in ('completed', 'failed', 'cancelled')
      and updated_at < now() - make_interval(days => p_commit_days)
    limit p_limit
  );
  get diagnostics v_commits = row_count;
  delete from public.agent_workers
  where id in (
    select id from public.agent_workers
    where heartbeat_at < now() - make_interval(hours => p_worker_hours)
    limit p_limit
  );
  get diagnostics v_workers = row_count;
  return query select v_events, v_commits, v_workers;
end;
$$;

-- Name: delete_conversation_graph(text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.delete_conversation_graph(p_conversation_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_conversation_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  SELECT id
  INTO v_conversation_id
  FROM public.conversations
  WHERE id::text = p_conversation_id
    AND user_id = v_user_id
  FOR UPDATE;
  IF v_conversation_id IS NULL THEN
    RETURN false;
  END IF;
  DELETE FROM public.knowledge_entries e
  USING public.knowledge_bases kb
  WHERE e.kb_id = kb.id AND kb.user_id = v_user_id
    AND e.source_type = 'conversation' AND e.source_id = p_conversation_id;
  DELETE FROM public.archived_sources
  WHERE source_type = 'conversation'
    AND source_id = p_conversation_id
    AND user_id = v_user_id;
  DELETE FROM public.conversations
  WHERE id = v_conversation_id
    AND user_id = v_user_id;
  RETURN true;
END;
$$;

-- Name: delete_history_item_and_conversation(text, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.delete_history_item_and_conversation(p_history_type text, p_history_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_user_id uuid;
  v_table_name text;
  v_conversation_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  CASE p_history_type
    WHEN 'tarot' THEN v_table_name := 'tarot_readings';
    WHEN 'liuyao' THEN v_table_name := 'liuyao_divinations';
    WHEN 'mbti' THEN v_table_name := 'mbti_readings';
    WHEN 'hepan' THEN v_table_name := 'hepan_charts';
    WHEN 'palm' THEN v_table_name := 'palm_readings';
    WHEN 'face' THEN v_table_name := 'face_readings';
    WHEN 'qimen' THEN v_table_name := 'qimen_charts';
    WHEN 'daliuren' THEN v_table_name := 'daliuren_divinations';
    WHEN 'meihua' THEN v_table_name := 'meihua_divinations';
    WHEN 'xiaoliuren' THEN v_table_name := 'xiaoliuren_divinations';
    ELSE RAISE EXCEPTION 'invalid history type' USING ERRCODE = '22023';
  END CASE;
  EXECUTE format(
    'SELECT conversation_id FROM public.%I WHERE id::text = $1 AND user_id = $2 FOR UPDATE',
    v_table_name
  ) INTO v_conversation_id USING p_history_id, v_user_id;
  IF NOT FOUND THEN RETURN false; END IF;
  EXECUTE format(
    'DELETE FROM public.%I WHERE id::text = $1 AND user_id = $2',
    v_table_name
  ) USING p_history_id, v_user_id;
  IF v_conversation_id IS NOT NULL THEN
    PERFORM public.delete_conversation_graph(v_conversation_id::text);
  END IF;
  RETURN true;
END;
$_$;

-- Name: deliver_daily_briefing_notices(integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.deliver_daily_briefing_notices(p_limit integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE job public.daily_briefing_jobs; count_sent integer:=0;
BEGIN
 PERFORM public.agent_require_admin();
 FOR job IN SELECT * FROM public.daily_briefing_jobs WHERE status='completed' AND notification_pending ORDER BY created_at LIMIT least(greatest(p_limit,1),100) FOR UPDATE SKIP LOCKED LOOP
  BEGIN
   IF NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=job.user_id AND (NOT notifications_enabled OR NOT notify_site)) AND job.result_conversation_id IS NOT NULL THEN
    INSERT INTO public.notifications(user_id,type,title,content,link,event_key,event_data) VALUES(job.user_id,'system','你的早报已生成',job.local_date::text||' 的早报已送达，消耗 1 积分。','/chat?id='||job.result_conversation_id,'briefing:'||job.id,jsonb_build_object('conversationId',job.result_conversation_id,'briefingId',job.id)) ON CONFLICT(user_id,event_key) WHERE event_key IS NOT NULL DO NOTHING;
   END IF;
   UPDATE public.daily_briefing_jobs SET notification_pending=false WHERE id=job.id; count_sent:=count_sent+1;
  EXCEPTION WHEN OTHERS THEN NULL; -- Retry delivery only; keep the saved result and settled charge.
  END;
 END LOOP;
 RETURN count_sent;
END;
$$;

-- Name: fork_conversation_snapshot(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.fork_conversation_snapshot(p_parent uuid, p_through text, p_source_messages jsonb, p_messages jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE parent public.conversations; target jsonb;
BEGIN
 SELECT * INTO parent FROM public.conversations WHERE id=p_parent AND user_id=auth.uid() FOR UPDATE;
 IF parent.id IS NULL THEN RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE='42501'; END IF;
 IF parent.messages IS DISTINCT FROM p_source_messages THEN RAISE EXCEPTION 'BRANCH_CHANGED' USING ERRCODE='40001'; END IF;
 SELECT value INTO target FROM jsonb_array_elements(parent.messages) WHERE value->>'id'=p_through;
 IF target IS NULL OR target->>'role'<>'assistant' OR (target->'agent' IS NOT NULL AND target#>>'{agent,status}'<>'completed') THEN RAISE EXCEPTION 'ANSWER_NOT_COMPLETED' USING ERRCODE='22023'; END IF;
 RETURN public.create_conversation_with_messages(auth.uid(),coalesce(parent.title,'对话')||' · 分叉',parent.personality,NULL,jsonb_build_object('kind','fork','parentConversationId',p_parent,'parentMessageId',p_through),p_messages);
END;
$$;

-- Name: get_conversation_share(text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.get_conversation_share(p_token text) RETURNS TABLE(title text, snapshot jsonb, include_charts boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
 SELECT s.title, s.snapshot, s.include_charts, s.created_at, s.updated_at
   FROM public.conversation_shares s
  WHERE p_token ~ '^[A-Za-z0-9_-]{43}$' AND s.token=p_token AND s.revoked_at IS NULL
  LIMIT 1
$_$;

-- Name: guard_user_entitlement_writes(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.guard_user_entitlement_writes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_owner name;
BEGIN
    SELECT pg_catalog.pg_get_userbyid(c.relowner) INTO v_owner
    FROM pg_catalog.pg_class c WHERE c.oid = TG_RELID;
    -- Effective SQL identity survives nested SECURITY DEFINER RPCs. Never use
    -- session_user or the JWT role to decide whether this is an owner write.
    IF current_user = v_owner OR current_user = 'service_role' THEN
        RETURN NEW;
    END IF;
    IF current_user = 'authenticated' AND public.is_admin_user() IS TRUE THEN
        RETURN NEW;
    END IF;
    IF current_user <> 'authenticated' OR auth.uid() IS NULL
       OR NEW.id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'Account writes require the authenticated owner' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.is_admin IS DISTINCT FROM false
           OR NEW.membership IS DISTINCT FROM 'free'::text
           OR NEW.membership_expires_at IS NOT NULL
           OR NEW.ai_chat_count IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION 'Account entitlement changes require administrator authority' USING ERRCODE = '42501';
        END IF;
    ELSIF ROW(NEW.id, NEW.is_admin, NEW.membership, NEW.membership_expires_at, NEW.ai_chat_count)
          IS DISTINCT FROM
          ROW(OLD.id, OLD.is_admin, OLD.membership, OLD.membership_expires_at, OLD.ai_chat_count) THEN
        RAISE EXCEPTION 'Account entitlement changes require administrator authority' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;

-- Name: handle_user_created(); Type: FUNCTION; Schema: identity; Owner: -
CREATE FUNCTION identity.handle_user_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.users (id, nickname, avatar_url, membership, ai_chat_count)
  VALUES (
    NEW.id,
    COALESCE(NULLIF(btrim(NEW.name), ''), '命理爱好者'),
    NEW.image,
    'free',
    1
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

-- Name: import_ming_records_and_notes(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.import_ming_records_and_notes(p_records jsonb, p_notes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_records_imported integer := 0;
  v_notes_imported integer := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(jsonb_typeof(p_records), 'null') <> 'array' THEN
    RAISE EXCEPTION 'records must be an array' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(jsonb_typeof(p_notes), 'null') <> 'array' THEN
    RAISE EXCEPTION 'notes must be an array' USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.ming_records
  WHERE user_id = v_user_id;
  DELETE FROM public.ming_notes
  WHERE user_id = v_user_id;
  INSERT INTO public.ming_records (
    user_id,
    title,
    content,
    category,
    tags,
    event_date,
    related_chart_type,
    related_chart_id,
    is_pinned,
    created_at,
    updated_at
  )
  SELECT
    v_user_id,
    record.title,
    record.content,
    COALESCE(record.category, 'general'),
    CASE
      WHEN record.tags IS NULL THEN '{}'::text[]
      ELSE ARRAY(SELECT jsonb_array_elements_text(record.tags))
    END,
    record.event_date,
    record.related_chart_type,
    record.related_chart_id,
    COALESCE(record.is_pinned, false),
    COALESCE(record.created_at, now()),
    COALESCE(record.updated_at, now())
  FROM jsonb_to_recordset(p_records) AS record(
    title text,
    content text,
    category text,
    tags jsonb,
    event_date date,
    related_chart_type text,
    related_chart_id uuid,
    is_pinned boolean,
    created_at timestamptz,
    updated_at timestamptz
  );
  GET DIAGNOSTICS v_records_imported = ROW_COUNT;
  INSERT INTO public.ming_notes (
    user_id,
    note_date,
    content,
    mood,
    created_at,
    updated_at
  )
  SELECT
    v_user_id,
    COALESCE(note.note_date, CURRENT_DATE),
    note.content,
    note.mood,
    COALESCE(note.created_at, now()),
    COALESCE(note.updated_at, now())
  FROM jsonb_to_recordset(p_notes) AS note(
    note_date date,
    content text,
    mood text,
    created_at timestamptz,
    updated_at timestamptz
  );
  GET DIAGNOSTICS v_notes_imported = ROW_COUNT;
  RETURN jsonb_build_object(
    'recordsImported', v_records_imported,
    'notesImported', v_notes_imported
  );
END;
$$;

-- Name: increment_ai_chat_count(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.increment_ai_chat_count(user_id uuid, amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_count integer;
BEGIN
IF auth.role() <> 'service_role' THEN
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
END IF;
  IF amount IS NULL OR amount <= 0 THEN
    RAISE EXCEPTION 'amount must be greater than zero' USING ERRCODE = '22023';
  END IF;
  UPDATE public.users
  SET
    ai_chat_count = COALESCE(ai_chat_count, 0) + amount,
    updated_at = now()
  WHERE id = user_id
  RETURNING ai_chat_count INTO new_count;
  IF new_count IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM public.record_credit_transaction(
    user_id,
    amount,
    'refund',
    'ai_refund',
    new_count,
    'credit_refund',
    NULL,
    format('AI 失败退款 +%s 积分', amount),
    '{}'::jsonb
  );
  RETURN new_count;
END;
$$;

-- Name: increment_community_post_view_count(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.increment_community_post_view_count(post_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE public.community_posts
  SET view_count = view_count + 1
  WHERE id = post_id
  RETURNING view_count INTO updated_count;
  RETURN updated_count;
END;
$$;

-- Name: is_admin_user(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.is_admin_user() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.id = auth.uid() AND u.is_admin = true
  );
$$;

-- Name: kb_replace_source_entries(uuid, text, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.kb_replace_source_entries(p_kb_id uuid, p_source_type text, p_source_id text, p_entries jsonb, p_archive boolean DEFAULT false, p_user_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_user_id uuid;
  v_rows integer := 0;
BEGIN
  IF COALESCE(jsonb_typeof(p_entries), 'null') <> 'array' THEN
    RAISE EXCEPTION 'entries must be an array' USING ERRCODE = '22023';
  END IF;
  IF auth.role() = 'service_role' THEN
    v_actor_user_id := p_user_id;
    IF v_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'user required for service role' USING ERRCODE = '22023';
    END IF;
  ELSIF auth.uid() IS NOT NULL THEN
    v_actor_user_id := auth.uid();
  ELSE
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.knowledge_bases
    WHERE id = p_kb_id
      AND user_id = v_actor_user_id
  ) THEN
    RAISE EXCEPTION 'knowledge base not found' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtext(p_kb_id::text),
    hashtext(p_source_type || ':' || p_source_id)
  );
  DELETE FROM public.knowledge_entries
  WHERE kb_id = p_kb_id
    AND source_type = p_source_type
    AND source_id = p_source_id
    AND chunk_index >= jsonb_array_length(p_entries);
  INSERT INTO public.knowledge_entries (
    kb_id,
    content,
    content_vector,
    source_type,
    source_id,
    chunk_index,
    metadata
  )
  SELECT
    p_kb_id,
    entry_row.content,
    NULL,
    p_source_type,
    p_source_id,
    entry_row.chunk_index,
    COALESCE(entry_row.metadata, '{}'::jsonb)
  FROM jsonb_to_recordset(p_entries) AS entry_row(
    content text,
    chunk_index integer,
    metadata jsonb
  )
  ON CONFLICT (kb_id, source_type, source_id, chunk_index) DO UPDATE
  SET
    content = EXCLUDED.content,
    content_vector = NULL,
    metadata = EXCLUDED.metadata;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF p_archive THEN
    INSERT INTO public.archived_sources (
      user_id,
      kb_id,
      source_type,
      source_id
    )
    VALUES (
      v_actor_user_id,
      p_kb_id,
      p_source_type,
      p_source_id
    )
    ON CONFLICT (source_type, source_id, kb_id) DO UPDATE
    SET user_id = EXCLUDED.user_id;
  END IF;
  RETURN v_rows;
END;
$$;

-- Name: kb_unarchive_source_as_service(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.kb_unarchive_source_as_service(p_user_id uuid, p_kb_id uuid, p_source_type text, p_source_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.knowledge_bases
    WHERE id = p_kb_id
      AND user_id = p_user_id
  ) THEN
    RETURN false;
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtext(p_kb_id::text),
    hashtext(p_source_type || ':' || p_source_id)
  );
  DELETE FROM public.knowledge_entries
  WHERE kb_id = p_kb_id
    AND source_type = p_source_type
    AND source_id = p_source_id;
  DELETE FROM public.archived_sources
  WHERE user_id = p_user_id
    AND kb_id = p_kb_id
    AND source_type = p_source_type
    AND source_id = p_source_id;
  RETURN true;
END;
$$;

-- Name: membership_credit_limit(text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.membership_credit_limit(p_plan_id text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_plan_id
    WHEN 'pro' THEN 50
    WHEN 'plus' THEN 20
    ELSE 10
  END
$$;

-- Name: membership_rank(text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.membership_rank(p_plan_id text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_plan_id
    WHEN 'pro' THEN 2
    WHEN 'plus' THEN 1
    ELSE 0
  END
$$;

-- Name: orphan_agent_attachment(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.orphan_agent_attachment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 UPDATE public.agent_attachments SET orphaned_at=now() WHERE id=OLD.attachment_id AND NOT EXISTS(SELECT 1 FROM public.agent_attachment_refs WHERE attachment_id=OLD.attachment_id);
 RETURN OLD;
END;
$$;

-- Name: perform_daily_checkin_as_service(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.perform_daily_checkin_as_service(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := current_date;
  v_current_credits integer := 0;
  v_new_credits integer := 0;
  v_membership text := 'free';
  v_membership_expires_at timestamptz;
  v_effective_membership text := 'free';
  v_credit_limit integer := 10;
  v_base_reward integer := 1;
  v_reward_credits integer := 0;
BEGIN
IF auth.role() <> 'service_role' THEN
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
END IF;
  SELECT
    COALESCE(ai_chat_count, 0),
    COALESCE(membership, 'free'),
    membership_expires_at
  INTO
    v_current_credits,
    v_membership,
    v_membership_expires_at
  FROM public.users
  WHERE id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'user_not_found');
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.daily_checkins
    WHERE user_id = p_user_id
      AND checkin_date = v_today
  ) THEN
    RETURN jsonb_build_object(
      'status', 'already_checked_in',
      'reward_credits', 0
    );
  END IF;
  IF v_membership IN ('plus', 'pro')
    AND v_membership_expires_at IS NOT NULL
    AND v_membership_expires_at > now() THEN
    v_effective_membership := v_membership;
  END IF;
  v_credit_limit := public.membership_credit_limit(v_effective_membership);
  IF v_current_credits >= v_credit_limit THEN
    RETURN jsonb_build_object(
      'status', 'credit_cap_reached',
      'reward_credits', 0,
      'credits', v_current_credits,
      'credit_limit', v_credit_limit
    );
  END IF;
  v_base_reward := FLOOR(random() * 3)::integer + 1;
  v_reward_credits := CASE v_effective_membership
    WHEN 'pro' THEN v_base_reward * 3
    WHEN 'plus' THEN v_base_reward * 2
    ELSE v_base_reward
  END;
  v_new_credits := v_current_credits + v_reward_credits;
  INSERT INTO public.daily_checkins (
    user_id,
    checkin_date,
    reward_credits
  ) VALUES (
    p_user_id,
    v_today,
    v_reward_credits
  );
  UPDATE public.users
  SET
    ai_chat_count = v_new_credits,
    updated_at = now()
  WHERE id = p_user_id;
  PERFORM public.record_credit_transaction(
    p_user_id,
    v_reward_credits,
    'earn',
    'checkin',
    v_new_credits,
    'daily_checkin',
    v_today::text,
    format('每日签到 +%s 积分', v_reward_credits),
    jsonb_build_object('membership', v_effective_membership, 'base_reward', v_base_reward)
  );
  RETURN jsonb_build_object(
    'status', 'ok',
    'reward_credits', v_reward_credits,
    'credits', v_new_credits,
    'membership', v_effective_membership,
    'credit_limit', v_credit_limit
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'status', 'already_checked_in',
      'reward_credits', 0
    );
END;
$$;

-- Name: process_scheduled_reminder_delivery_as_service(uuid, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.process_scheduled_reminder_delivery_as_service(p_reminder_id uuid, p_stale_before timestamp with time zone, p_notification_title text, p_notification_content text, p_notification_link text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed public.scheduled_reminders;
  v_claimed_at timestamptz := now();
  v_should_notify boolean := false;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.scheduled_reminders
  SET sent_at = v_claimed_at
  WHERE id = p_reminder_id
    AND sent = false
    AND (sent_at IS NULL OR sent_at <= p_stale_before)
  RETURNING *
  INTO v_claimed;
  IF v_claimed.id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_claimed');
  END IF;
  SELECT
    COALESCE(rs.enabled, false)
    AND COALESCE(rs.notify_site, false)
    AND COALESCE(us.notifications_enabled, true)
    AND COALESCE(us.notify_site, true)
  INTO v_should_notify
  FROM (SELECT 1) seed
  LEFT JOIN public.reminder_subscriptions rs
    ON rs.user_id = v_claimed.user_id
   AND rs.reminder_type = v_claimed.reminder_type
  LEFT JOIN public.user_settings us
    ON us.user_id = v_claimed.user_id;
  IF NOT v_should_notify THEN
    UPDATE public.scheduled_reminders
    SET
      sent = true,
      sent_at = v_claimed_at
    WHERE id = v_claimed.id
      AND sent = false
      AND sent_at = v_claimed_at;
    RETURN jsonb_build_object('status', 'skipped');
  END IF;
  INSERT INTO public.notifications (
    user_id,
    type,
    title,
    content,
    link
  )
  VALUES (
    v_claimed.user_id,
    'system',
    p_notification_title,
    p_notification_content,
    p_notification_link
  );
  UPDATE public.scheduled_reminders
  SET
    sent = true,
    sent_at = v_claimed_at
  WHERE id = v_claimed.id
    AND sent = false
    AND sent_at = v_claimed_at;
  RETURN jsonb_build_object('status', 'sent');
END;
$$;

-- Name: protect_fork_history(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.protect_fork_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE original jsonb; replacement jsonb;
BEGIN
 FOR original IN SELECT value FROM jsonb_array_elements(coalesce(OLD.messages,'[]')) WHERE value#>>'{metadata,forkHistory}'='true' LOOP
  SELECT value INTO replacement FROM jsonb_array_elements(coalesce(NEW.messages,'[]')) WHERE value->>'id'=original->>'id';
  IF replacement IS DISTINCT FROM original THEN RAISE EXCEPTION 'FORK_HISTORY_READ_ONLY' USING ERRCODE='22023'; END IF;
 END LOOP;
 RETURN NEW;
END;
$$;

-- Name: record_credit_transaction(uuid, integer, text, text, integer, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.record_credit_transaction(p_user_id uuid, p_amount integer, p_type text, p_source text, p_balance_after integer, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_transaction_id uuid;
BEGIN
  INSERT INTO public.credit_transactions (
    user_id,
    amount,
    type,
    source,
    description,
    balance_after,
    reference_type,
    reference_id,
    metadata
  )
  VALUES (
    p_user_id,
    p_amount,
    p_type,
    p_source,
    p_description,
    p_balance_after,
    p_reference_type,
    p_reference_id,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_transaction_id;
  RETURN v_transaction_id;
END;
$$;

-- Name: replace_conversation_messages(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.replace_conversation_messages(p_conversation_id uuid, p_messages jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(jsonb_typeof(p_messages), 'null') <> 'array' THEN
    RAISE EXCEPTION 'messages must be an array' USING ERRCODE = '22023';
  END IF;
  SELECT user_id
  INTO v_owner
  FROM public.conversations
  WHERE id = p_conversation_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'conversation not found';
  END IF;
  IF auth.uid() IS NOT NULL
    AND auth.uid() <> v_owner
    AND NOT public.is_admin_user()
  THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;
  UPDATE public.conversations
  SET messages = COALESCE(p_messages, '[]'::jsonb),
      updated_at = now()
  WHERE id = p_conversation_id;
  DELETE FROM public.conversation_messages
  WHERE conversation_id = p_conversation_id;
  INSERT INTO public.conversation_messages (
    conversation_id,
    sequence,
    message_id,
    role,
    content,
    metadata,
    created_at
  )
  SELECT
    p_conversation_id,
    elements.ordinality::integer - 1,
    COALESCE(elements.value->>'id', gen_random_uuid()::text),
    COALESCE(elements.value->>'role', 'assistant'),
    COALESCE(elements.value->>'content', ''),
    (elements.value - 'id' - 'role' - 'content' - 'createdAt'),
    COALESCE(NULLIF(elements.value->>'createdAt', '')::timestamptz, now())
  FROM jsonb_array_elements(COALESCE(p_messages, '[]'::jsonb)) WITH ORDINALITY AS elements(value, ordinality);
END;
$$;

-- Name: revoke_conversation_share(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.revoke_conversation_share(p_conversation uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.conversations WHERE id=p_conversation AND user_id=auth.uid()) THEN
  RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE='42501';
 END IF;
 UPDATE public.conversation_shares SET revoked_at=now(), updated_at=now(), snapshot='[]'::jsonb, title=''
  WHERE conversation_id=p_conversation AND user_id=auth.uid() AND revoked_at IS NULL;
 RETURN FOUND;
END;
$$;

