$$;

-- Name: save_bazi_case_profile_as_service(uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.save_bazi_case_profile_as_service(p_user_id uuid, p_chart_id uuid, p_master_review jsonb, p_owner_feedback jsonb, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(jsonb_typeof(p_events), 'null') <> 'array' THEN
    RAISE EXCEPTION 'events must be an array' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.bazi_charts
    WHERE id = p_chart_id
      AND user_id = p_user_id
  ) THEN
    RETURN jsonb_build_object('status', 'chart_not_found');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('bazi_case_profile'), hashtext(p_chart_id::text));
  INSERT INTO public.bazi_case_profiles (
    user_id,
    bazi_chart_id,
    master_review,
    owner_feedback,
    updated_at
  )
  VALUES (
    p_user_id,
    p_chart_id,
    p_master_review,
    p_owner_feedback,
    now()
  )
  ON CONFLICT (bazi_chart_id) DO UPDATE
  SET
    user_id = EXCLUDED.user_id,
    master_review = EXCLUDED.master_review,
    owner_feedback = EXCLUDED.owner_feedback,
    updated_at = now()
  RETURNING id
  INTO v_profile_id;
  DELETE FROM public.bazi_case_events
  WHERE profile_id = v_profile_id
    AND user_id = p_user_id;
  INSERT INTO public.bazi_case_events (
    profile_id,
    user_id,
    bazi_chart_id,
    event_date,
    category,
    title,
    detail
  )
  SELECT
    v_profile_id,
    p_user_id,
    p_chart_id,
    event_date,
    category,
    title,
    NULLIF(detail, '')
  FROM jsonb_to_recordset(p_events) AS event_row(
    event_date date,
    category text,
    title text,
    detail text
  );
  RETURN jsonb_build_object(
    'status', 'ok',
    'profile_id', v_profile_id
  );
END;
$$;

-- Name: schedule_reminder_if_absent_as_service(uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.schedule_reminder_if_absent_as_service(p_user_id uuid, p_reminder_type text, p_scheduled_for timestamp with time zone, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted_id uuid;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.scheduled_reminders (
    user_id,
    reminder_type,
    scheduled_for,
    content
  )
  VALUES (
    p_user_id,
    p_reminder_type,
    p_scheduled_for,
    p_content
  )
  ON CONFLICT (user_id, reminder_type, scheduled_for) DO NOTHING
  RETURNING id
  INTO v_inserted_id;
  RETURN v_inserted_id IS NOT NULL;
END;
$$;

-- Name: search_conversation_messages(text, integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.search_conversation_messages(p_query text, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '3s'
    AS $$
DECLARE pattern text; result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF length(trim(p_query)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'invalid search query'; END IF;
  pattern := '%' || replace(replace(replace(trim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  SELECT coalesce(jsonb_agg(to_jsonb(search_rows)), '[]'::jsonb) INTO result FROM (
    (SELECT c.id AS "conversationId", c.title, NULL::text AS "messageId", c.title AS preview, c.updated_at AS "updatedAt"
      FROM public.conversations c WHERE c.user_id=auth.uid() AND c.title ILIKE pattern ESCAPE '\' ORDER BY c.updated_at DESC LIMIT 10)
    UNION ALL
    (SELECT c.id, c.title, m.message_id, substr(m.content, greatest(1, strpos(lower(m.content),lower(trim(p_query)))-80), 300), c.updated_at
      FROM public.conversation_messages m JOIN public.conversations c ON c.id=m.conversation_id
      WHERE c.user_id=auth.uid() AND m.role <> 'system' AND m.content ILIKE pattern ESCAPE '\'
      ORDER BY c.updated_at DESC,m.sequence LIMIT least(greatest(p_limit,1),30))
  ) search_rows;
  RETURN result;
END;
$$;

-- Name: search_knowledge_fts(text, uuid[], integer, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.search_knowledge_fts(p_query text, p_kb_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 20, p_config text DEFAULT 'simple'::text) RETURNS TABLE(id uuid, kb_id uuid, content text, metadata jsonb, rank real)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_user_id UUID;
    v_safe_config regconfig;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    v_safe_config := CASE
        WHEN p_config = 'english' THEN 'pg_catalog.english'::regconfig
        ELSE 'pg_catalog.simple'::regconfig
    END;
    RETURN QUERY
    SELECT e.id, e.kb_id, e.content, e.metadata,
        ts_rank(to_tsvector(v_safe_config, e.content), plainto_tsquery(v_safe_config, p_query))
    FROM public.knowledge_entries e
    JOIN public.knowledge_bases kb ON e.kb_id = kb.id
    WHERE kb.user_id = v_user_id
      AND (p_kb_ids IS NULL OR e.kb_id = ANY(p_kb_ids))
      AND to_tsvector(v_safe_config, e.content) @@ plainto_tsquery(v_safe_config, p_query)
    ORDER BY 5 DESC
    LIMIT p_limit;
END;
$$;

-- Name: search_knowledge_trigram(text, uuid[], integer, real); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.search_knowledge_trigram(p_query text, p_kb_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 20, p_threshold real DEFAULT 0.3) RETURNS TABLE(id uuid, kb_id uuid, content text, metadata jsonb, similarity real)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    RETURN QUERY
    SELECT e.id, e.kb_id, e.content, e.metadata, similarity(e.content, p_query)
    FROM public.knowledge_entries e
    JOIN public.knowledge_bases kb ON e.kb_id = kb.id
    WHERE kb.user_id = v_user_id
      AND (p_kb_ids IS NULL OR e.kb_id = ANY(p_kb_ids))
      AND similarity(e.content, p_query) > p_threshold
    ORDER BY 5 DESC
    LIMIT p_limit;
END;
$$;

-- Name: search_knowledge_vector(double precision[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.search_knowledge_vector(p_query_vector double precision[], p_kb_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 20, p_dim integer DEFAULT 1536) RETURNS TABLE(id uuid, kb_id uuid, content text, metadata jsonb, distance real)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
declare
  v_user_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;
  if array_length(p_query_vector, 1) != p_dim then
    raise exception 'Query vector dimension (%) does not match p_dim (%)',
      array_length(p_query_vector, 1), p_dim;
  end if;
  return query execute format('
    select e.id, e.kb_id, e.content, e.metadata,
      (e.content_vector::extensions.vector(%s) <=> $1::extensions.vector(%s))::real as distance
    from public.knowledge_entries e
    join public.knowledge_bases kb on e.kb_id = kb.id
    where kb.user_id = $2
      and ($3 is null or e.kb_id = any($3))
      and e.embedding_dim = $4
    order by e.content_vector::extensions.vector(%s) <=> $1::extensions.vector(%s)
    limit $5', p_dim, p_dim, p_dim, p_dim)
  using p_query_vector::extensions.vector, v_user_id, p_kb_ids, p_dim, p_limit;
end;
$_$;

-- Name: settle_daily_briefing(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.settle_daily_briefing(p_id uuid, p_token uuid, p_content text, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE job public.daily_briefing_jobs; conversation uuid;
BEGIN
 PERFORM public.agent_require_admin();
 SELECT * INTO job FROM public.daily_briefing_jobs WHERE id=p_id FOR UPDATE;
 IF job.id IS NULL OR job.status<>'generating' OR job.lease_token IS DISTINCT FROM p_token OR job.lease_until<=now() THEN RETURN false; END IF;
 IF job.deadline<=now() OR NOT EXISTS(SELECT 1 FROM public.reminder_subscriptions WHERE user_id=job.user_id AND reminder_type='daily_briefing' AND enabled) THEN
  p_content:=NULL; p_error:='当天截止或订阅已关闭'; job.attempts:=3;
 END IF;
 IF p_error IS NULL AND length(btrim(coalesce(p_content,'')))>=20 AND length(p_content)<=64000 THEN
  conversation:=public.create_conversation_with_messages(job.user_id,'早报 · '||job.local_date::text,'general',NULL,jsonb_build_object('kind','daily_briefing','jobId',job.id,'localDate',job.local_date,'timezone',job.timezone),
    jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'role','assistant','content',p_content,'createdAt',now(),'metadata',jsonb_build_object('dailyBriefingJobId',job.id))));
  UPDATE public.daily_briefing_jobs SET status='completed',billing='settled',content=p_content,result_conversation_id=conversation,notification_pending=true,lease_token=NULL,lease_until=NULL,error=NULL,updated_at=now() WHERE id=job.id;
 ELSE
  IF job.attempts>=3 AND job.billing='reserved' THEN PERFORM public.increment_ai_chat_count(job.user_id,1); END IF;
  UPDATE public.daily_briefing_jobs SET status=CASE WHEN job.attempts>=3 THEN 'failed' ELSE 'pending' END,billing=CASE WHEN job.attempts>=3 AND billing='reserved' THEN 'refunded' ELSE billing END,lease_token=NULL,lease_until=NULL,error=left(coalesce(p_error,'早报内容为空或无效'),500),updated_at=now() WHERE id=job.id;
 END IF;
 RETURN true;
END;
$$;

-- Name: submit_community_report_and_notify(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.submit_community_report_and_notify(p_target_type text, p_target_id uuid, p_reason text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_report public.community_reports;
  v_user_id uuid := auth.uid();
  v_post_id uuid;
  v_link text := format('/community/%s', p_target_id);
  v_content text := format('目标类型：%s，原因：%s', p_target_type, p_reason);
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.community_reports (
    reporter_id,
    target_type,
    target_id,
    reason,
    description
  )
  VALUES (
    v_user_id,
    p_target_type,
    p_target_id,
    p_reason,
    NULLIF(p_description, '')
  )
  RETURNING *
  INTO v_report;
  IF p_target_type = 'comment' THEN
    SELECT post_id
    INTO v_post_id
    FROM public.community_comments
    WHERE id = p_target_id;
    IF v_post_id IS NOT NULL THEN
      v_link := format('/community/%s', v_post_id);
    END IF;
  END IF;
  IF NULLIF(p_description, '') IS NOT NULL THEN
    v_content := v_content || '，描述：' || p_description;
  END IF;
  INSERT INTO public.notifications (
    user_id,
    type,
    title,
    content,
    link
  )
  SELECT
    u.id,
    'system',
    '有新的社区举报',
    v_content,
    v_link
  FROM public.users u
  LEFT JOIN public.user_settings s
    ON s.user_id = u.id
  WHERE u.is_admin = true
    AND COALESCE(s.notifications_enabled, true)
    AND COALESCE(s.notify_site, true);
  RETURN jsonb_build_object(
    'status', 'ok',
    'report', to_jsonb(v_report)
  );
END;
$$;

-- Name: sync_agent_attachment_refs(); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.sync_agent_attachment_refs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE owner_id uuid; document jsonb; ids uuid[]; a public.agent_attachments;
BEGIN
 IF TG_TABLE_NAME='conversations' THEN owner_id:=NEW.user_id; document:=coalesce(NEW.messages,'[]');
 ELSE SELECT user_id INTO owner_id FROM public.agent_runs WHERE id=NEW.run_id; document:=NEW.message; END IF;
 SELECT coalesce(array_agg(DISTINCT value::uuid),'{}') INTO ids FROM jsonb_path_query(document,'lax $.**.attachments.ids[*]') valueset(element),LATERAL (SELECT element#>>'{}' AS value) extracted
 WHERE value ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
 FOR a IN SELECT * FROM public.agent_attachments WHERE id=ANY(ids) OR id IN (
   SELECT attachment_id FROM public.agent_attachment_refs WHERE
    (TG_TABLE_NAME='conversations' AND conversation_id=(to_jsonb(NEW)->>'id')::uuid) OR
    (TG_TABLE_NAME='agent_run_commands' AND command_sequence=(to_jsonb(NEW)->>'sequence')::bigint)
 ) ORDER BY id FOR UPDATE LOOP
   IF a.id=ANY(ids) AND (a.user_id IS DISTINCT FROM owner_id OR a.status<>'ready') THEN RAISE EXCEPTION 'ATTACHMENT_NOT_AVAILABLE' USING ERRCODE='42501'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.agent_attachments WHERE id=ANY(ids) AND user_id=owner_id AND status='ready')<>cardinality(ids) THEN RAISE EXCEPTION 'ATTACHMENT_NOT_AVAILABLE' USING ERRCODE='42501'; END IF;
 IF TG_TABLE_NAME='conversations' THEN
   DELETE FROM public.agent_attachment_refs WHERE conversation_id=NEW.id AND NOT attachment_id=ANY(ids);
   INSERT INTO public.agent_attachment_refs(attachment_id,conversation_id) SELECT unnest(ids),NEW.id ON CONFLICT DO NOTHING;
 ELSE
   DELETE FROM public.agent_attachment_refs WHERE command_sequence=NEW.sequence AND (NOT attachment_id=ANY(ids) OR NEW.delivery_state IN ('cancelled','consumed'));
   IF NEW.delivery_state NOT IN ('cancelled','consumed') THEN INSERT INTO public.agent_attachment_refs(attachment_id,command_sequence) SELECT unnest(ids),NEW.sequence ON CONFLICT DO NOTHING; END IF;
 END IF;
 UPDATE public.agent_attachments SET orphaned_at=NULL WHERE id=ANY(ids) AND EXISTS(SELECT 1 FROM public.agent_attachment_refs WHERE attachment_id=id);
 RETURN NEW;
END;
$_$;

-- Name: toggle_community_vote(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.toggle_community_vote(p_target_type text, p_target_id uuid, p_vote_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_existing public.community_votes;
  v_vote text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_target_type NOT IN ('post', 'comment') THEN
    RAISE EXCEPTION 'invalid target_type' USING ERRCODE = '22023';
  END IF;
  IF p_vote_type NOT IN ('up', 'down') THEN
    RAISE EXCEPTION 'invalid vote_type' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('community-vote:%s:%s:%s', v_user_id, p_target_type, p_target_id), 0)
  );
  SELECT *
  INTO v_existing
  FROM public.community_votes
  WHERE user_id = v_user_id
    AND target_type = p_target_type
    AND target_id = p_target_id
  FOR UPDATE;
  IF v_existing.id IS NULL THEN
    INSERT INTO public.community_votes (
      user_id,
      target_type,
      target_id,
      vote_type
    )
    VALUES (
      v_user_id,
      p_target_type,
      p_target_id,
      p_vote_type
    )
    RETURNING vote_type
    INTO v_vote;
  ELSIF v_existing.vote_type = p_vote_type THEN
    DELETE FROM public.community_votes
    WHERE id = v_existing.id;
    v_vote := NULL;
  ELSE
    UPDATE public.community_votes
    SET vote_type = p_vote_type
    WHERE id = v_existing.id
    RETURNING vote_type
    INTO v_vote;
  END IF;
  RETURN jsonb_build_object(
    'status', 'ok',
    'vote', v_vote
  );
END;
$$;

-- Name: toggle_ming_record_pin(uuid); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.toggle_ming_record_pin(p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record public.ming_records;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  UPDATE public.ming_records
  SET
    is_pinned = NOT COALESCE(is_pinned, false),
    updated_at = now()
  WHERE id = p_record_id
    AND user_id = auth.uid()
  RETURNING *
  INTO v_record;
  IF v_record.id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  RETURN jsonb_build_object(
    'status', 'ok',
    'record', to_jsonb(v_record)
  );
END;
$$;

