-- Name: update_conversation_with_messages(uuid, text, boolean, text, boolean, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
CREATE FUNCTION public.update_conversation_with_messages(p_conversation_id uuid, p_title text DEFAULT NULL::text, p_title_present boolean DEFAULT false, p_personality text DEFAULT NULL::text, p_personality_present boolean DEFAULT false, p_messages jsonb DEFAULT NULL::jsonb, p_messages_present boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_owner uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  SELECT user_id
  INTO v_owner
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF NOT public.is_admin_user() AND v_actor_id <> v_owner THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_messages_present AND COALESCE(jsonb_typeof(p_messages), 'null') <> 'array' THEN
    RAISE EXCEPTION 'messages must be an array' USING ERRCODE = '22023';
  END IF;
  UPDATE public.conversations
  SET
    title = CASE WHEN p_title_present THEN p_title ELSE title END,
    personality = CASE WHEN p_personality_present THEN p_personality ELSE personality END,
    updated_at = now()
  WHERE id = p_conversation_id;
  IF p_messages_present THEN
    PERFORM public.replace_conversation_messages(p_conversation_id, COALESCE(p_messages, '[]'::jsonb));
  END IF;
  RETURN jsonb_build_object('status', 'ok');
END;
$$;

