-- Name: conversations_with_archive_status; Type: VIEW; Schema: public; Owner: -
CREATE VIEW public.conversations_with_archive_status WITH (security_invoker='on') AS
 SELECT id,
    user_id,
    personality,
    title,
    messages,
    created_at,
    updated_at,
    source_type,
    source_data,
    (EXISTS ( SELECT 1
           FROM public.archived_sources a
          WHERE ((a.source_type = 'conversation'::text) AND (a.source_id = (c.id)::text) AND (a.user_id = c.user_id)))) AS is_archived,
    ( SELECT array_agg(a.kb_id) AS array_agg
           FROM public.archived_sources a
          WHERE ((a.source_type = 'conversation'::text) AND (a.source_id = (c.id)::text) AND (a.user_id = c.user_id))) AS archived_kb_ids,
    (EXISTS ( SELECT 1
           FROM public.agent_runs r
          WHERE ((r.conversation_id = c.id) AND (r.user_id = c.user_id)))) AS has_agent_run
   FROM public.conversations c;

-- Name: ming_records_with_archive_status; Type: VIEW; Schema: public; Owner: -
CREATE VIEW public.ming_records_with_archive_status WITH (security_invoker='on') AS
 SELECT id,
    user_id,
    title,
    content,
    category,
    tags,
    event_date,
    related_chart_type,
    related_chart_id,
    is_pinned,
    created_at,
    updated_at,
    (EXISTS ( SELECT 1
           FROM public.archived_sources a
          WHERE ((a.source_type = 'record'::text) AND (a.source_id = (r.id)::text)))) AS is_archived,
    ( SELECT array_agg(a.kb_id) AS array_agg
           FROM public.archived_sources a
          WHERE ((a.source_type = 'record'::text) AND (a.source_id = (r.id)::text))) AS archived_kb_ids
   FROM public.ming_records r;
